    if(hs){cur={sport:/^(NCAAF|CFB|COLLEGE)/i.test(hs[1])?'ncaaf':/^(NHL|HOCKEY)/i.test(hs[1])?'nhl':hs[1].toLowerCase(),lines:[]};sections.push(cur);return;}
    if(!cur){cur={sport:null,lines:[]};sections.push(cur);}
