  const P=D.p[id]||(D.p[id]={name,team,n:0,s:{}});
  if(eventId){const h=String(eventId).slice(-6);P.ev=P.ev||[];if(P.ev.includes(h))return false;P.ev.push(h);if(P.ev.length>24)P.ev=P.ev.slice(-24);}
