const MS_CATS={warmup:'🌱 Warm-ups',penny:'🪙 Penny stocks',house:'🏠 House money',compound:'📈 Compound interest',steady:'🐢 Steady pace',ladder:'🎲 Ladders & heists',multi:'🧺 Multi-bankroll',rules:'🎭 Character & rule challenges',sprint:'⏱ Sprints'};
const MS_TEMPLATES={};MS_LIB.forEach(r=>{MS_TEMPLATES[r[0]]={id:r[0],cat:r[1],name:r[2],start:r[3],goal:r[4],days:r[5],route:r[6],rule:r[7],sport:r[8],note:r[9],pots:r[10]||null};});
const msParse=key=>{const [route,k,f,unit]=String(key||'').split('|');return{route,cfg:{k:k?+k:undefined,f:f?+f:undefined,unit:unit?+unit:undefined}};};
const msRouteKey=r=>R_(r.route,r.cfg.k,r.cfg.f,r.cfg.unit);
function msRouteLabel(r){const R=MS_ROUTES[r.route]||{name:r.route};return R.name+(r.cfg.k?` · ${r.cfg.k}-leg`:'')+(r.cfg.f?` · ${Math.round(r.cfg.f*100)}%`:'')+(r.cfg.unit?` · $${r.cfg.unit} base`:'');}
function msRng(seed){let a=seed>>>0;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
/* Leg profile for simulation: price and hit chance, scaled by your own edge. */
function msLegProfile(rule,p){const F=MS_FILTERS[rule]||{};const dec=F.dec||americanToDecimal(-110),fair=F.fair||0.5;
  return{dec,p:Math.max(0.05,Math.min(0.92,fair*(p/0.5)))};}
/* Stake a route puts down today. */
function msStakeFor(route,cfg,b,potStart){
  if(route==='snowball'||route==='heist'||route==='elevator')return b;
  if(route==='stairs'||route==='compound')return Math.max(1,b*cfg.f);
  if(route==='housemoney')return Math.min(b,(cfg.unit||1)+(cfg.f||0.5)*Math.max(0,b-potStart));
  if(route==='drip')return Math.min(b,cfg.unit||1);
  if(route==='twolane')return Math.max(1,b*0.2);
  return Math.max(1,b*0.25);
}
/* Simulate a whole mission (one or more pots) day by day. */
function msSimPots(pots,goal,days,runs,seed,cps){
  const rnd=msRng(seed);let ok=0,bust=0;const hit=[];
  const tk=(k,stake,L)=>{for(let i=0;i<k;i++)if(rnd()>=L.p)return 0;return stake*Math.pow(L.dec,k);};
  for(let r=0;r<runs;r++){
    const S=pots.map(P=>({b:P.bal,safe:0,start:P.start,cp:0}));let won=false,d;
    for(d=1;d<=days;d++){
      pots.forEach((P,i)=>{const s=S[i];if(s.b<1)return;const{route,cfg}=P;const L=P.L;
        if(route==='twolane'){const st=Math.max(1,s.b*0.2);if(st>s.b)return;s.b=s.b-st+tk(2,st*0.6,L)+tk(4,st*0.4,L);return;}
        const st=Math.min(s.b,msStakeFor(route,cfg,s.b,s.start));const ret=tk(cfg.k||2,st,L);
        if(route==='heist'&&ret>0){const prof=ret-st;s.safe+=prof*0.25;s.b=s.b-st+ret-prof*0.25;}else s.b=s.b-st+ret;
        if(route==='elevator'&&cps){const tot=s.b+s.safe;while(s.cp<cps.length&&tot>=cps[s.cp]){s.safe+=s.b*0.5;s.b*=0.5;s.cp++;}}});
      const tot=S.reduce((a,s)=>a+s.b+s.safe,0);if(tot>=goal){won=true;break;}
      if(S.every(s=>s.b<1))break;}
    if(won){ok++;hit.push(d);}else if(S.every(s=>s.b<1))bust++;}
  hit.sort((a,b)=>a-b);return{p:ok/runs,bust:bust/runs,median:hit.length?hit[Math.floor(hit.length/2)]:null};
}
function msPotsOf(m){ // one uniform view over single- and multi-pot missions
  if(m.pots&&m.pots.length)return m.pots;
  return[{name:'Main',share:1,routeKey:m.routeKey,rule:m.rule||null,sport:m.sport||null,balance:m.balance,start:m.start,safe:m.safe||0}];
}
function msSimFor(m,potsOverride,runs,seedExtra){
  const X=msMath(m);const pots=(potsOverride||msPotsOf(m)).map(P=>{const r=msParse(P.routeKey||msRouteKey(msBestSingle(m)));
    return{...r,bal:P.balance,start:P.start,L:msLegProfile(P.rule,X.R.p)};});
  const cps=msCheckpoints(m).map(c=>c.amt);
  return msSimPots(pots,m.goal,X.daysLeft,runs||2000,(m.id||1)+(seedExtra||0)+Math.round(m.balance*100),cps);
}
const MS_PLAN_CACHE={};
/* Route planner — alternatives for single-pot missions, ranked by finish %. */
function msRoutes(m){
  const X=msMath(m);const key=[m.id,m.balance,X.daysLeft,X.R.p.toFixed(3),m.goal,m.rule||'',m.routeKey||''].join('|');if(MS_PLAN_CACHE[key])return MS_PLAN_CACHE[key];
  const keys=new Set();[2,3,4].forEach(k=>{keys.add(R_('snowball',k));keys.add(R_('heist',k));});
  [[2,.25],[2,.4],[3,.2],[3,.35]].forEach(([k,f])=>keys.add(R_('stairs',k,f)));keys.add(R_('twolane'));
  [[3,.5],[4,.5]].forEach(([k,f])=>keys.add(R_('housemoney',k,f,1)));keys.add(R_('elevator',3));keys.add(R_('compound',1,.1));
  if(m.routeKey)keys.add(m.routeKey);
  const P0=msPotsOf(m)[0];let i=0;
  const res=[...keys].map(k=>{const r=msParse(k);return{...r,...msSimFor(m,[{...P0,routeKey:k}],1500,(i++)*7919)};});
  res.sort((a,b)=>b.p-a.p||(a.bust-b.bust));return(MS_PLAN_CACHE[key]=res);
}
function msBestSingle(m){const M={...m};delete M.routeKey;const k=[m.id,'best',m.balance].join('|');if(MS_PLAN_CACHE[k])return MS_PLAN_CACHE[k];
  const keys=[R_('housemoney',3,.5,1),R_('stairs',2,.25),R_('snowball',3),R_('heist',3),R_('compound',1,.1)];
  const best=keys.map((kk,i)=>({...msParse(kk),...msSimFor(M,[{balance:m.balance,start:m.start,routeKey:kk,rule:m.rule}],800,i*131)})).sort((a,b)=>b.p-a.p)[0];
  return(MS_PLAN_CACHE[k]=best);}
function msActiveRoute(m){if(m.pots)return null;if(!m.routeKey)return msBestSingle(m);const all=msRoutes(m);return all.find(r=>msRouteKey(r)===m.routeKey)||{...msParse(m.routeKey),...msSimFor(m,null,1500)};}
function msSetSport(id,v){const A=msAll();const m=A.find(x=>x.id===id);if(!m)return;m.sport=v==='all'?null:v;msSave(A);msRender();}
function msPickRoute(id,key){const A=msAll();const m=A.find(x=>x.id===id);if(!m)return;m.routeKey=key;msSave(A);msRender();}
function msCheckpoints(m){const G=m.goal/m.start;return MS_CHECKPOINTS.map((n,i)=>({name:n,amt:Math.round(m.start*Math.pow(G,(i+1)/MS_CHECKPOINTS.length))}));}
function msDifficulty(p){return MS_DIFF.find(d=>p>=d[0]);}
/* Build a ticket from Today's card that obeys the mission's rule and sport. */
function msBuildTicket(k,minDec,rule,sport){
  const T=get(TC_KEY,{})||{};const by=T.d===today()?T.by||{}:{};const F=MS_FILTERS[rule];
  const pool=[];Object.entries(by).forEach(([sp,B])=>{if(sport&&sp!==sport)return;(B.picks||[]).forEach(x=>{if(x.price==null)return;if(!tcIsToday(x))return;if(onTicketMatch(sp,x.game,x.m,x.sd))return;
    const X={...x,sp};if(F&&!F.f(X))return;pool.push(X);});});
  pool.sort((a,b)=>b.rank-a.rank);const top=pool.slice(0,10);
  let best=null;const pick=(start,cur)=>{if(cur.length===k){if(new Set(cur.map(x=>x.sp+x.game)).size<k)return;
      if(F&&F.cross&&new Set(cur.map(x=>x.sp)).size<2)return;
      const d=cur.reduce((a,x)=>a*americanToDecimal(x.price),1),q=cur.reduce((a,x)=>a+x.rank,0),okP=d>=minDec*0.999;
      if(!best||(okP&&!best.ok)||(okP===best.ok&&(okP?q>best.q:d>best.d)))best={legs:[...cur],d,q,ok:okP};return;}
    for(let i=start;i<top.length;i++){cur.push(top[i]);pick(i+1,cur);cur.pop();}};
  pick(0,[]);return{best,poolN:pool.length};
}
function msLegInfo(l){const sp=l.sport||'mlb';const[a,h]=String(l.game).split('@');const k=sqKey(sp,{away:{abbr:a},home:{abbr:h}},l.pick);
  const T=get(TC_KEY,{})||{};const B=((T.by||{})[sp])||{};const x=k?(B.picks||[]).find(p=>p.game===l.game&&p.m===k.market&&p.sd===k.side):null;return{sp,k,x:x?{...x,sp}:null};}
/* Does an attached ticket follow the mission's rule? */
function msRuleCheck(t,rule,sport){
  const L=(t&&t.legs)||[];if(!L.length)return{ok:false,why:'empty ticket'};const I=L.map(msLegInfo);
  if(sport&&I.some(i=>i.sp!==sport))return{ok:false,why:SPORT_LAB[sport]+' — a leg is from another sport'};
  const F=MS_FILTERS[rule];if(!F)return{ok:true};
  if(F.cross)return new Set(I.map(i=>i.sp)).size>=2?{ok:true}:{ok:false,why:'needs 2+ sports'};
  const bad=L.filter((l,i)=>{const x=I[i].x||{sp:I[i].sp,price:l.price,m:I[i].k&&I[i].k.market,sd:I[i].k&&I[i].k.side,chars:[],rules:[]};return!F.f(x);});
  return bad.length?{ok:false,why:`${bad.length} leg${bad.length>1?'s':''} break "${F.lab}": ${bad.map(l=>l.pick).join(', ')}`}:{ok:true};
}
const MS_QUESTS=[
  {id:'gold',name:'Gold Rush',xp:50,desc:'every leg SUPREME or STRONG'},
  {id:'clean',name:'Clean Hands',xp:25,desc:'no 🧊 fades, no conflicts'},
  {id:'key',name:'Key Master',xp:30,desc:'a football side past a key number'},
  {id:'money',name:'Follow the Money',xp:40,desc:'a 💰 sharp-split side'},
  {id:'cross',name:'World Tour',xp:30,desc:'legs from 2+ sports'},
  {id:'crowd',name:'Full Council',xp:40,desc:'4+ characters on every leg'},
  {id:'clv',name:'Beat the Close',xp:60,desc:'every priced leg beats the close'}
];
function msQuestsToday(m){const h=[...(today()+m.id)].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,7);
  const a=h%MS_QUESTS.length,b=(a+1+(h>>>5)%(MS_QUESTS.length-1))%MS_QUESTS.length;return[MS_QUESTS[a],MS_QUESTS[b]];}
function msCheckQuest(q,t){
  const L=(t&&t.legs)||[];if(!L.length)return false;const I=L.map(msLegInfo);
  if(q.id==='gold')return I.every(i=>i.x&&(i.x.color===' supreme'||i.x.color===' strong'));
  if(q.id==='clean')return I.every(i=>!i.x||!(i.x.rules||[]).some(r=>r.icon==='🧊'));
  if(q.id==='key')return I.some(i=>i.x&&(i.x.rules||[]).some(r=>r.icon==='🔑'&&/is past/.test(r.text)));
  if(q.id==='money')return I.some(i=>i.x&&(i.x.rules||[]).some(r=>r.icon==='💰'));
  if(q.id==='cross')return new Set(I.map(i=>i.sp)).size>=2;
  if(q.id==='crowd')return I.every(i=>i.x&&(i.x.chars||[]).length>=4);
  if(q.id==='clv'){const c=L.map(l=>{try{return clvLeg(l,t)}catch(e){return null}}).filter(Boolean);return c.length===L.filter(l=>l.price!=null).length&&c.length>0&&c.every(x=>(x.pct!=null?x.pct:x.pts)>0);}
  return false;
}
function msXP(){let g=0;try{g=msgGet().xp||0;}catch(e){}return msAll().reduce((a,m)=>a+(m.xp||0),0)+g;}
function msRank(xp){let r=MS_RANKS[0];MS_RANKS.forEach(x=>{if(xp>=x[0])r=x;});const nx=MS_RANKS.find(x=>x[0]>xp);return{name:r[1],next:nx};}
function msStart(id,scope){
  const T=MS_TEMPLATES[id]||MS_TEMPLATES[{ladder:'ladder',heist:'heist',grind:'grind',weekend:'weekend_warrior',custom:'custom'}[id]];if(!T)return;
  let start=T.start,goal=T.goal,days=T.days;
  if(T.id==='custom'){start=+prompt('Starting balance $',T.start)||T.start;goal=+prompt('Goal $',T.goal)||T.goal;days=+prompt('Days',T.days)||T.days;}
  const m={id:Date.now()+Math.floor(Math.random()*1000),type:T.id,name:T.name,start,goal,days,startDate:today(),balance:start,attempt:1,steps:[],status:'active',
    routeKey:T.route||null,rule:T.rule||null,sport:scope===undefined?(T.sport||null):(scope==='all'?null:scope),xp:0,safe:0,legs:T.route?(msParse(T.route).cfg.k||2):2};
  if(T.pots){m.pots=T.pots.map(([name,share,route,rule,sport])=>({name,share,routeKey:route,rule:rule||null,sport:sport||null,start:+(start*share).toFixed(2),balance:+(start*share).toFixed(2),safe:0}));m.routeKey=null;}
  try{const S=msSimFor(m,null,1500);m.diff=msDifficulty(S.p)[1];m.p0=S.p;}catch(e){}
  const A=msAll();A.push(m);msSave(A);msRender();
}
function msRestart(id){const A=msAll();const m=A.find(x=>x.id===id);if(!m)return;m.balance=m.start;m.safe=0;m.attempt++;m.steps=[];m.status='active';m.startDate=today();m.cpBank=0;
  if(m.pots)m.pots.forEach(P=>{P.balance=P.start;P.safe=0;});msSave(A);msRender();}
/* Settle attached tickets. Each step belongs to a pot (Main for single-pot missions). */
function msSync(){
  const A=msAll();const L=get(LS.locked,[]);let ch=false;
  A.forEach(m=>{if(m.status!=='active')return;const pots=m.pots;let settled=false;
    m.steps.forEach(s=>{if(s.done)return;const t=L.find(x=>String(x.id)===String(s.ticketId));if(!t)return;
      let done=false,rec=null;try{done=ticketIsComplete(t);rec=done?ticketRecord(t):null}catch(e){}
      if(!done)return;const M=ticketMoney(t);const stake=M?M.stake:0;
      s.done=true;s.won=rec.l===0&&rec.w>0;s.stake=stake;s.payout=s.won&&M?M.payout:0;
      const P=pots?pots[s.pot||0]:null;const rk=(P?P.routeKey:(s.route||m.routeKey))||'';
      let cut=0;if(s.won&&rk.startsWith('heist')){cut=+((s.payout-stake)*0.25).toFixed(2);}
      if(P){P.balance=+(P.balance-stake+s.payout-cut).toFixed(2);P.safe=+((P.safe||0)+cut).toFixed(2);}
      else{m.balance=+(m.balance-stake+s.payout-cut).toFixed(2);m.safe=+((m.safe||0)+cut).toFixed(2);}
      if(s.won&&rk.startsWith('elevator')){const cps=msCheckpoints(m);m.cpBank=m.cpBank||0;
        while(m.cpBank<cps.length&&(m.balance+(m.safe||0))>=cps[m.cpBank].amt){const half=+(m.balance/2).toFixed(2);m.balance=+(m.balance-half).toFixed(2);m.safe=+((m.safe||0)+half).toFixed(2);m.cpBank++;}}
      (s.quests||[]).forEach(q=>{if(q.id==='clv'&&q.done==null){const ok=msCheckQuest({id:'clv'},t);q.done=ok;if(ok)m.xp=(m.xp||0)+q.xp;}});
      ch=true;settled=true;});
    if(settled&&m.status==='active'&&!pots)try{msAdapt(m);}catch(e){console.warn('adapt',e);}
    if(pots){m.balance=+pots.reduce((a,P)=>a+P.balance,0).toFixed(2);m.safe=+pots.reduce((a,P)=>a+(P.safe||0),0).toFixed(2);}
    const tot=m.balance+(m.safe||0);
    try{const cps=msCheckpoints(m);m.cpHit=m.cpHit||[];cps.forEach(c=>{if(tot>=c.amt&&!m.cpHit.some(x=>x.amt===c.amt))m.cpHit.push({amt:c.amt,name:c.name,d:today()});});}catch(e){}
    if(tot>=m.goal){m.status='won';const D=MS_DIFF.find(d=>d[1]===m.diff)||MS_DIFF[1];const clean=m.steps.every(s=>!s.rule||s.rule.ok);
      m.xp=(m.xp||0)+D[3]+(clean?Math.round(D[3]/2):0);m.clean=clean;
      if((m.mut||[]).length&&m.steps.every(s=>s.mutOk!==false)){const mult=(m.mut||[]).reduce((a,k)=>a*((MSG_MUT[k]||{}).mult||1),1);m.xp+=Math.round(D[3]*(mult-1));m.mutWin=true;}}
    else if((pots?pots.every(P=>P.balance<1):m.balance<1)||(m.type==='ladder'&&m.steps.some(s=>s.done&&!s.won)))m.status='busted';
    const daysIn=Math.floor((Date.parse(today())-Date.parse(m.startDate))/864e5);
    if(m.status==='active'&&daysIn>=m.days)m.status='expired';
  });
  if(ch||A.some(m=>m.status!=='active'))msSave(A);return A;
}
/* ── ADAPTIVE ROUTING ─────────────────────────────────────────────────────
   After every settled step, measure pace: where the balance is vs where a
   straight-line (geometric) path from start to goal says it should be today.
   If you've fallen behind (or got ahead), re-simulate every route from your
   ACTUAL balance and days left, and switch to the one with the best finish
   chance — but only if it's a real improvement (3+ points). Every switch is
   logged with the numbers that drove it. Stakes always come from the live
   balance, so a $50 roll and a $200 roll get different orders automatically. */
function msPace(m){const days=Math.max(1,m.days);const t=Math.max(0,Math.min(days,Math.floor((Date.parse(today())-Date.parse(m.startDate))/864e5)));
  const ideal=m.start*Math.pow(m.goal/m.start,t/days);const have=m.balance+(m.safe||0);
  const left=Math.max(1,days-t);return{t,ideal,have,ratio:have/ideal,left,needPerDay:Math.pow(m.goal/Math.max(0.01,have),1/left)};}
function msAdapt(m){
  const pc=msPace(m);if(pc.ratio>=0.9&&pc.ratio<=1.25)return;
  const cur=m.routeKey||msRouteKey(msBestSingle(m));let opts=[];try{opts=msRoutes(m)||[];}catch(e){return;}
  /* never let the app itself escalate into all-in routes (snowball/heist/elevator)
     unless the mission was built all-in: adapting changes pace, not risk of ruin */
  const ALLIN=/^(snowball|heist|elevator)\|/;const tpl=(MS_TEMPLATES[m.type]||{}).route||m.routeKey||'';
  if(!ALLIN.test(tpl))opts=opts.filter(o=>!ALLIN.test(msRouteKey(o)));if(!opts.length)return;
  if(!opts.length)return;const best=opts.slice().sort((a,b)=>(b.p||0)-(a.p||0))[0];const bk=msRouteKey(best);
  const curOpt=opts.find(o=>msRouteKey(o)===cur);const pNow=curOpt?curOpt.p:null;
  const why0=pc.ratio<0.9?`behind pace (${Math.round(pc.ratio*100)}% of target)`:`ahead of pace (${Math.round(pc.ratio*100)}% of target)`;
  if(bk===cur||(pNow!=null&&(best.p-pNow)<0.03)){
    /* no route is meaningfully better — say so, once a day, with the numbers */
    const A=(m.adapt=m.adapt||[]);if(!A.some(x=>x.date===today()&&x.hold))
      A.push({date:today(),hold:true,from:cur,to:cur,ratio:+pc.ratio.toFixed(3),pFrom:pNow,pTo:pNow!=null?pNow:best.p,needPerDay:+pc.needPerDay.toFixed(3),
        why:`${why0} — kept route: no alternative finishes more often (needs ×${pc.needPerDay.toFixed(2)}/day for ${pc.left} days)`});
    return;}
  (m.adapt=m.adapt||[]).push({date:today(),from:cur,to:bk,ratio:+pc.ratio.toFixed(3),pFrom:pNow,pTo:best.p,needPerDay:+pc.needPerDay.toFixed(3),
    why:pc.ratio<0.9?`behind pace (${Math.round(pc.ratio*100)}% of target)`:`ahead of pace (${Math.round(pc.ratio*100)}% of target) — locking in safer`});
  m.routeKey=bk;Object.keys(MS_PLAN_CACHE).forEach(k=>delete MS_PLAN_CACHE[k]);
}
function msAdaptHtml(m){const a=(m.adapt||[]).slice(-3);if(!a.length)return'';
  return`<div class="sub mono" style="font-size:9.5px;color:var(--gold);margin-top:4px">${a.map(x=>x.hold?`⏸ ${x.date}: ${esc(x.why)}`:`↻ ${x.date}: ${esc(x.why)} · ${esc(msRouteLabel({...msParse(x.from)}))} → ${esc(msRouteLabel({...msParse(x.to)}))} · finish ${x.pFrom!=null?Math.round(x.pFrom*100)+'%':'?'} → ${Math.round(x.pTo*100)}%`).join('<br>')}</div>`;}
/* ── ROADMAP: the full day-by-day path, with your real balance laid over it ── */
function msRoadmapToggle(id){try{msgFlag('roadmap');}catch(e){}const el=document.getElementById('msRM_'+id);if(!el)return;
  if(el.style.display!=='none'){el.style.display='none';return;}const m=msAll().find(x=>String(x.id)===String(id));if(!m)return;el.innerHTML=msRoadmapHtml(m);el.style.display='block';}
function msRoadmapHtml(m){
  const days=m.days,G=m.goal/m.start,daily=Math.pow(G,1/days);const pc=msPace(m);
  /* actual balance by day, replayed from settled steps */
  const bal={};let b=m.start;const done=(m.steps||[]).filter(s=>s.done).sort((a,c)=>String(a.date).localeCompare(String(c.date)));
  done.forEach(s=>{b=+(b-(s.stake||0)+(s.payout||0)).toFixed(2);bal[s.date]=b;});
  const step=days<=31?1:days<=90?3:7;let last=m.start;const cps=msCheckpoints(m);const rows=[];
  for(let d=0;d<=days;d+=step){const date=dayShift(m.startDate,d);const tgt=m.start*Math.pow(G,d/days);
    Object.keys(bal).filter(x=>x<=date).forEach(x=>{last=bal[x];});
    const past=d<=pc.t;const cp=cps.find(c=>c.amt>=m.start*Math.pow(G,Math.max(0,d-step)/days)&&c.amt<=tgt);
    rows.push(`<tr style="${d===pc.t?'background:rgba(245,165,36,.12)':''}"><td>${d===pc.t?'▶ ':''}Day ${d}</td><td>${date.slice(5)}</td><td>$${tgt.toFixed(tgt<100?2:0)}</td>
      <td style="color:${!past?'var(--mute)':last>=tgt?'var(--win)':'var(--rust)'}">${past?'$'+last.toFixed(2):'—'}</td><td style="color:var(--gold)">${cp?esc(cp.name):''}</td></tr>`);}
  const lane=(()=>{try{const o=msOrders(m);return o.lanes.map(x=>`${x.lab}: $${x.stake} on ${x.k}-leg${x.minDec?` at ${decimalToAmerican(x.minDec)} or better`:''}`).join(' · ');}catch(e){return'';}})();
  return`<div class="tkt" style="margin-top:6px"><h3>🗺 Roadmap · $${m.start} → $${m.goal.toLocaleString()} in ${days} days</h3>
    <div class="sub mono">Path needs ×${daily.toFixed(3)} per day (${((daily-1)*100).toFixed(1)}%/day). Today: day ${pc.t}, target $${pc.ideal.toFixed(2)}, you have $${pc.have.toFixed(2)} (${Math.round(pc.ratio*100)}% of pace).
    From here you need ×${pc.needPerDay.toFixed(3)}/day for ${pc.left} days.</div>
    ${lane?`<div class="sub mono" style="margin-top:4px">Today's orders → ${esc(lane)}</div>`:''}
    <div style="overflow-x:auto"><table class="mono" style="width:100%;font-size:10px;text-align:center;margin-top:6px"><tr style="color:var(--mute)"><td>day</td><td>date</td><td>target</td><td>actual</td><td>checkpoint</td></tr>${rows.join('')}</table></div>
    ${msAdaptHtml(m)}<div class="sub" style="font-size:9.5px;color:var(--mute)">Target is the geometric path from start to goal. Fall behind or get well ahead and the route re-plans itself from your real balance.</div></div>`;}
/* ══ THE GAME LAYER — campaign, daily 3, process streak, bosses, trophies,
   mutators, custom runs ════════════════════════════════════════════════════
   Design rules (Octalysis research): reward skill and discipline (beating the
   close, following the plan, staying inside limits), not volume or risk.
   Streaks count PROCESS days, carry freeze tokens and never punish a day off
   hard. Chasing a loss costs XP. All awards are idempotent — recomputed from
   real data every render, granted once.                                     */
const MSG_KEY='d4.msgame';
function msgGet(){const G=get(MSG_KEY,null)||{};G.xp=G.xp||0;G.ach=G.ach||{};G.daily=G.daily||{};G.boss=G.boss||{};G.flags=G.flags||{};
  G.streak=G.streak||{cur:0,best:0,last:null,freezes:1};G.ch=G.ch||{};G.log=G.log||[];return G;}
function msgSave(G){G.log=G.log.slice(-60);set(MSG_KEY,G);}
function msgAward(G,xp,why){G.xp=Math.max(0,G.xp+xp);G.log.push({d:today(),xp,why});MSG_FX.push({xp,why});}
const MSG_FX=[];
function msgFlag(k){const G=msgGet();if(!G.flags[k]){G.flags[k]=today();msgSave(G);}}
/* ── fast, cached reads of settled tickets ── */
let MSG_TC=null,MSG_TS=0;
function msgTickets(){if(MSG_TC&&Date.now()-MSG_TS<60e3)return MSG_TC;const out=[];
  (get(LS.locked,[])||[]).forEach(t=>{if(!t.legs||!t.legs.length)return;let done=false,rec=null;try{done=ticketIsComplete(t);rec=done?ticketRecord(t):null;}catch(e){}
    if(!done||!rec)return;const won=rec.l===0&&rec.w>0;const M=(()=>{try{return ticketMoney(t)}catch(e){return null}})();
    out.push({t,date:String(t.date||'').slice(0,10),won,legs:t.legs.length,stake:M?M.stake:0,sports:[...new Set(t.legs.map(l=>l.sport||'mlb'))],
      plus:t.legs.length===1&&+t.legs[0].price>0,clv:(()=>{try{return msCheckQuest({id:'clv'},t)}catch(e){return false}})()});});
  MSG_TC=out;MSG_TS=Date.now();return out;}
const msgWeekKey=d=>{const x=new Date(String(d||today())+'T12:00:00Z');const day=(x.getUTCDay()+6)%7;x.setUTCDate(x.getUTCDate()-day);return x.toISOString().slice(0,10);};
const msgInWeek=(d,wk)=>d>=wk&&d<=dayShift(wk,6);
/* ── DAILY 3: process objectives, measured from real data ── */
const MSG_DAILY=[
  {id:'card',icon:'📋',name:'Load today\'s board',desc:'Today\'s card has picks from at least one sport',test:d=>{const T=get(TC_KEY,{})||{};return T.d===d&&Object.values(T.by||{}).some(B=>(B.picks||[]).length);}},
  {id:'attach',icon:'🎯',name:'Play your plan',desc:'Attach a ticket to a running mission',test:d=>msAll().some(m=>(m.steps||[]).some(s=>s.date===d))},
  {id:'limit',icon:'🛡',name:'Stay inside the lines',desc:'Bet today and keep every stake within your daily limit',test:d=>{const T=(get(LS.locked,[])||[]).filter(t=>String(t.date||'').slice(0,10)===d);
     if(!T.length)return false;let sum=0;T.forEach(t=>{try{const M=ticketMoney(t);sum+=M?M.stake:0;}catch(e){}});const lim=(()=>{try{return dailyLimit()}catch(e){return 0}})();return !lim||sum<=lim+1e-9;}}];
function msgDailyState(d){d=d||today();return MSG_DAILY.map(o=>{let ok=false;try{ok=!!o.test(d);}catch(e){}return{...o,ok};});}
/* ── WEEKLY BOSS: synthesizes skills, one per week, health bar = what's left ── */
const MSG_BOSSES=[
  {id:'closer',icon:'⏱',name:'The Closer',desc:'Beat the closing line on 5 settled bets',hp:5,dmg:(W)=>W.filter(x=>x.clv).length},
  {id:'dogs',icon:'🐕',name:'Underdog Uprising',desc:'Win 3 plus-money singles',hp:3,dmg:(W)=>W.filter(x=>x.plus&&x.won).length},
  {id:'parlay',icon:'🧩',name:'The Parlay Pilgrim',desc:'Cash a parlay of 3+ legs',hp:1,dmg:(W)=>W.filter(x=>x.legs>=3&&x.won).length},
  {id:'iron',icon:'🛡',name:'Iron Discipline',desc:'5 days this week inside your daily limit (with a bet placed)',hp:5,dmg:(W,wk)=>{let n=0;for(let i=0;i<7;i++){const d=dayShift(wk,i);if(d>today())break;try{if(MSG_DAILY[2].test(d))n++;}catch(e){}}return n;}},
  {id:'sharp',icon:'🌟',name:'The Sharp Eye',desc:'A day where the Best card goes 4-1 or better',hp:1,dmg:(W,wk)=>{const B=get('d4.best5log',{})||{};return Object.entries(B).filter(([d,E])=>msgInWeek(d,wk)&&(E.picks||[]).filter(x=>x.hit===true).length>=4).length;}},
  {id:'maestro',icon:'🎼',name:'Multi-Sport Maestro',desc:'Win tickets in 3 different sports',hp:3,dmg:(W)=>new Set(W.filter(x=>x.won).flatMap(x=>x.sports)).size},
  {id:'grinder',icon:'⚙',name:'The Grinder',desc:'Settle 8 mission steps',hp:8,dmg:(W,wk)=>msAll().reduce((a,m)=>a+(m.steps||[]).filter(s=>s.done&&msgInWeek(s.date,wk)).length,0)},
  {id:'climber',icon:'🧗',name:'Checkpoint Climber',desc:'Clear 2 mission checkpoints',hp:2,dmg:(W,wk)=>msAll().reduce((a,m)=>a+(m.cpHit||[]).filter(c=>msgInWeek(c.d,wk)).length,0)}];
function msgBoss(wk){wk=wk||msgWeekKey();const i=Math.floor(Date.parse(wk)/(7*864e5))%MSG_BOSSES.length;const B=MSG_BOSSES[(i+MSG_BOSSES.length)%MSG_BOSSES.length];
  const W=msgTickets().filter(x=>msgInWeek(x.date,wk));const d=Math.min(B.hp,B.dmg(W,wk)||0);return{...B,wk,dealt:d,dead:d>=B.hp};}
/* ── TROPHIES: rarity tiers, real progress bars ── */
const MSG_RAR={common:['Common','#9aa4b2',25],rare:['Rare','#4ea8ff',75],epic:['Epic','#b06cff',200],legendary:['Legendary','#ffb020',500]};
function msgStats(){const A=msAll(),T=msgTickets(),G=msgGet();const won=A.filter(m=>m.status==='won');
  const calR=(()=>{try{return calRows()}catch(e){return[]}})();
  return{won:won.length,cats:new Set(won.map(m=>(MS_TEMPLATES[m.type]||{}).cat).filter(Boolean)).size,steps:A.reduce((a,m)=>a+(m.steps||[]).filter(s=>s.done).length,0),
    clv:T.filter(x=>x.clv).length,dogs:T.filter(x=>x.plus&&x.won).length,big:T.filter(x=>x.legs>=4&&x.won).length,sports:new Set(T.filter(x=>x.won).flatMap(x=>x.sports)).size,
    clean:won.filter(m=>m.clean).length,comeback:won.filter(m=>(m.adapt||[]).some(a=>/behind/.test(a.why))).length,mut2:won.filter(m=>(m.mut||[]).length>=2&&m.mutWin).length,
    cps:A.reduce((a,m)=>a+(m.cpHit||[]).length,0),streak:G.streak.best,bosses:Object.values(G.boss).filter(b=>b.dead).length,
    perfect:Object.values(get('d4.best5log',{})||{}).filter(E=>(E.picks||[]).length>=5&&E.picks.every(x=>x.hit===true)).length,
    tenk:won.filter(m=>m.type==='ten_k_dream').length,daily3:Object.values(G.daily).filter(x=>x.all).length,roadmap:G.flags.roadmap?1:0,
    xp:msXP(),calGap:calR.length>=200?(calECE(calR)*100):null,custom:A.filter(m=>String(m.type).startsWith('cust_')&&m.status==='won').length};}
