function msgBuilderHtml(){const routes=['stairs|1|0.1','stairs|2|0.2','compound|1|0.12','housemoney|3|0.5|1','housemoney|4|0.5|2','snowball|3','heist|3','elevator|3','drip|3||1'];
  const rules=Object.keys(MS_FILTERS||{});
  return`<details class="tkt msg-card"><summary><b>🛠 Build your own run</b> <span class="sub mono" style="font-size:10px">— set the numbers, see the real odds before you commit</span></summary>
    <div class="msg-grid"><label>Start $<input id="mbS" type="number" value="100" min="1"></label><label>Goal $<input id="mbG" type="number" value="500" min="2"></label><label>Days<input id="mbD" type="number" value="30" min="1" max="365"></label>
    <label>Route<select id="mbR">${routes.map(r=>`<option value="${r}">${esc(msRouteLabel(msParse(r)))}</option>`).join('')}</select></label>
    <label>Rule<select id="mbU"><option value="">none</option>${rules.map(r=>`<option>${r}</option>`).join('')}</select></label>
    <label>Sport<select id="mbP"><option value="">any</option>${['mlb','nfl','ncaaf','nhl','nba'].map(s=>`<option>${s}</option>`).join('')}</select></label>
    <label>Name<input id="mbN" type="text" placeholder="My run"></label></div>
    <div class="bar"><button onclick="msgBuilderOdds()">🎲 Check the odds</button><button class="primary" onclick="msgBuilderStart()">Start this run</button></div><div id="mbOut" class="sub mono"></div></details>`;}
function msgBuilderVals(){const v=id=>document.getElementById(id).value;return{start:Math.max(1,+v('mbS')||100),goal:Math.max(2,+v('mbG')||500),days:Math.max(1,Math.min(365,+v('mbD')||30)),
  route:v('mbR'),rule:v('mbU')||null,sport:v('mbP')||null,name:(v('mbN')||'').trim()||'Custom run'};}
function msgBuilderOdds(){const V=msgBuilderVals();const el=document.getElementById('mbOut');if(V.goal<=V.start){el.textContent='Goal must be above start.';return null;}
  const m={id:1,type:'cust_preview',name:V.name,start:V.start,goal:V.goal,days:V.days,startDate:today(),balance:V.start,steps:[],status:'active',routeKey:V.route,rule:V.rule,sport:V.sport,safe:0,legs:(msParse(V.route).cfg||{}).k||2};
  let p=null;try{const r=msSimFor(m,null,1500);p=r&&r.p!=null?r.p:null;}catch(e){}
  const D=p!=null?msDifficulty(p)||MS_DIFF[MS_DIFF.length-1]:null;
  el.innerHTML=p!=null?`Finish chance <b>${(p*100).toFixed(p<0.01?2:1)}%</b> → <b style="color:${D[2]}">${D[1]}</b> · ${D[3]} XP base · needs ×${Math.pow(V.goal/V.start,1/V.days).toFixed(3)}/day`:'Could not simulate — try a different route.';return D;}
function msgBuilderStart(){const V=msgBuilderVals();if(V.goal<=V.start)return msgBuilderOdds();const id='cust_'+Date.now().toString(36);
  const T={id,cat:'custom',name:'🛠 '+V.name,start:V.start,goal:V.goal,days:V.days,route:V.route,rule:V.rule,sport:V.sport,note:'Your build.',pots:null};
  const C=get('d4.mscustom',{})||{};C[id]=T;set('d4.mscustom',C);MS_TEMPLATES[id]=T;msStart(id);}
try{Object.assign(MS_TEMPLATES,get('d4.mscustom',{})||{});}catch(e){}
/* ── the hub at the top of the Money tab ── */
function msgRing(p,col,label,size){size=size||58;const deg=Math.max(0,Math.min(1,p))*360;
  return`<div class="msg-ring" style="width:${size}px;height:${size}px;background:conic-gradient(${col} ${deg}deg,var(--rule) 0)"><div><b>${label}</b></div></div>`;}
function msgHubHtml(){let G;try{G=msgTick();}catch(e){console.warn('game tick',e);G=msgGet();}
  const ds=msgDailyState();const B=msgBoss();const St=msgStats();const camp=msgCampaign();const S=G.streak;
  const fx=MSG_FX.splice(0).slice(-3);
  const daily=`<div class="msg-card tkt"><div class="msg-row"><b>Daily 3</b><span class="mono msg-streak" title="process days (2 of 3 objectives); freezes protect a missed day">🔥 ${S.live||0} day${S.live===1?'':'s'} · best ${S.best} · 🧊×${S.freezes}</span></div>
    ${ds.map(o=>`<div class="msg-obj${o.ok?' ok':''}">${o.ok?'✅':o.icon} <b>${esc(o.name)}</b> <span class="sub">${esc(o.desc)}</span> <span class="mono">+40</span></div>`).join('')}
    <div class="sub mono" style="font-size:9.5px">2 of 3 keeps the streak alive · all 3 = +60 bonus · a 7-day streak earns a freeze (max 3)</div></div>`;
  const hp=1-B.dealt/B.hp;
  const boss=`<div class="msg-card tkt msg-boss${B.dead?' dead':''}"><div class="msg-row"><b>${B.icon} Weekly boss: ${esc(B.name)}</b><span class="mono">+400 XP</span></div>
    <div class="sub">${esc(B.desc)} · week of ${B.wk.slice(5)}</div>
    <div class="msg-hp"><div style="width:${(hp*100).toFixed(0)}%"></div></div><div class="sub mono" style="font-size:10px">${B.dead?'💀 DEFEATED':`${B.hp-B.dealt} hit${B.hp-B.dealt===1?'':'s'} left (${B.dealt}/${B.hp})`}</div></div>`;
  const map=`<div class="msg-card tkt"><b>🗺 Campaign</b><div class="msg-map">${camp.map(c=>`<div class="msg-node${c.clear?' clear':c.open?' open':''}" title="${esc(c.name)}: win 3 to clear (+${300*(c.i+1)} XP)">
      ${msgRing(c.w/3,c.clear?'var(--win)':'var(--gold)',c.icon,52)}<div class="mono" style="font-size:9px">${esc(c.name)}<br>${Math.min(c.w,3)}/3${c.open?'':' 🔒'}</div></div>`).join('<div class="msg-path"></div>')}</div>
    <div class="sub" style="font-size:9.5px">Clear a chapter by winning 3 of its missions. Chapters unlock in order (2 wins opens the next) — free play is always available on the board below.</div></div>`;
  const tro=MSG_ACH.map(([id,icon,name,rar,desc,fn,tgt])=>{const got=G.ach[id];let v=0;try{v=fn(St)||0;}catch(e){}const R=MSG_RAR[rar];
    return`<div class="msg-tro${got?' got':''}" style="--rc:${R[1]}" title="${esc(desc)} · ${R[0]} · +${R[2]} XP"><div class="i">${got?icon:'🔒'}</div><div class="n">${esc(name)}</div>
      ${got?`<div class="r">${R[0]}</div>`:`<div class="msg-bar"><div style="width:${Math.min(100,v/tgt*100).toFixed(0)}%"></div></div><div class="r">${Math.min(v,tgt)}/${tgt}</div>`}</div>`;}).join('');
  const nGot=Object.keys(G.ach).length;
  const trophies=`<details class="msg-card tkt"${nGot?'':' open'}><summary><b>🏆 Trophy case</b> <span class="mono" style="font-size:10px">${nGot}/${MSG_ACH.length}</span></summary><div class="msg-tros">${tro}</div></details>`;
  const toast=fx.length?`<div class="msg-toast">${fx.map(f=>`<div>${f.xp>0?'+'+f.xp+' XP':f.xp+' XP'} · ${esc(f.why)}</div>`).join('')}<div class="msg-confetti">${'<i></i>'.repeat(18)}</div></div>`:'';
  return msgCss()+toast+daily+boss+map+msgBuilderHtml()+trophies;}
function msgCss(){return`<style>
.msg-card{position:relative;overflow:hidden}.msg-row{display:flex;justify-content:space-between;align-items:center;gap:6px}
.msg-streak{font-size:10.5px;color:var(--gold)}.msg-obj{font-size:11.5px;padding:5px 0;border-bottom:1px solid var(--rule)}.msg-obj.ok{opacity:.7}.msg-obj .sub{font-size:10px}
.msg-boss{border-color:#b0303a}.msg-boss.dead{border-color:var(--win);opacity:.85}.msg-hp{height:10px;border-radius:6px;background:var(--rule);margin:6px 0 2px;overflow:hidden}
.msg-hp>div{height:100%;background:linear-gradient(90deg,#ff4b5c,#ff9a3c);transition:width .6s}
.msg-map{display:flex;align-items:center;overflow-x:auto;gap:2px;padding:6px 0}.msg-node{text-align:center;min-width:64px;opacity:.45}.msg-node.open{opacity:1}.msg-node.clear{opacity:1;filter:drop-shadow(0 0 6px rgba(46,204,113,.6))}
.msg-path{flex:0 0 14px;height:2px;background:var(--rule)}
.msg-ring{border-radius:50%;display:grid;place-items:center;margin:0 auto}.msg-ring>div{width:76%;height:76%;border-radius:50%;background:var(--card,#161921);display:grid;place-items:center;font-size:18px}
.msg-tros{display:grid;grid-template-columns:repeat(auto-fill,minmax(92px,1fr));gap:6px;margin-top:6px}
.msg-tro{border:1.5px solid var(--rule);border-radius:10px;padding:6px;text-align:center;font-size:10px;opacity:.55}
.msg-tro.got{opacity:1;border-color:var(--rc);box-shadow:0 0 10px -2px var(--rc)}.msg-tro .i{font-size:22px}.msg-tro .n{font-weight:800}.msg-tro .r{color:var(--rc);font-size:9px}
.msg-bar{height:4px;background:var(--rule);border-radius:3px;margin:3px 0;overflow:hidden}.msg-bar>div{height:100%;background:var(--rc)}
.msg-chip{font-size:10px;padding:3px 7px;margin:2px;border-radius:12px;border:1px solid var(--rule);background:none;color:var(--chalk)}.msg-chip.on{border-color:var(--gold);background:rgba(245,165,36,.15)}
.msg-chip[disabled]{opacity:.5}.msg-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:6px;margin:6px 0}.msg-grid input,.msg-grid select{width:100%}
.msg-toast{position:relative;border:1.5px solid var(--gold);border-radius:12px;padding:8px 10px;margin-bottom:8px;font-weight:800;color:var(--gold);animation:msgPop .5s ease-out}
@keyframes msgPop{0%{transform:scale(.85);opacity:0}100%{transform:scale(1);opacity:1}}
.msg-confetti{position:absolute;inset:0;pointer-events:none}.msg-confetti i{position:absolute;top:-6px;width:6px;height:10px;border-radius:2px;animation:msgFall 1.6s ease-in forwards}
${Array.from({length:18},(_,i)=>`.msg-confetti i:nth-child(${i+1}){left:${(i*5.5+3)%100}%;background:${['#ffb020','#2ecc71','#4ea8ff','#ff4b5c','#b06cff'][i%5]};animation-delay:${(i%6)*0.08}s}`).join('')}
@keyframes msgFall{0%{transform:translateY(0) rotate(0);opacity:1}100%{transform:translateY(90px) rotate(540deg);opacity:0}}
@media (prefers-reduced-motion:reduce){.msg-toast,.msg-confetti i,.msg-hp>div{animation:none;transition:none}}
</style>`;}

function msAttach(id,sel,pot){const tid=sel.value;if(!tid)return;const A=msAll();const m=A.find(x=>x.id===id);if(!m)return;
  if(m.steps.some(s=>String(s.ticketId)===tid))return;const t=get(LS.locked,[]).find(x=>String(x.id)===tid);
  const P=m.pots?m.pots[pot||0]:null;const rule=P?P.rule:m.rule,sport=P?(P.sport||m.sport||null):m.sport;
  const qs=msQuestsToday(m).map(q=>({id:q.id,name:q.name,xp:q.xp,done:q.id==='clv'?null:msCheckQuest(q,t)}));
  qs.forEach(q=>{if(q.done)m.xp=(m.xp||0)+q.xp;});
  const rc=msRuleCheck(t,rule,sport);
  const rk=P?P.routeKey:(m.routeKey||msRouteKey(msActiveRoute(m)));
  const plannedK=(msParse(rk||'').cfg||{}).k||null;const actualK=t&&t.legs?t.legs.length:null;
  /* planned stake for this order, from the live balance */
  let plan=null;try{const pr=msParse(rk||'');plan=+msStakeFor(pr.route,pr.cfg||{},P?P.balance:m.balance,P?P.start:m.start).toFixed(2);}catch(e){}
  let mutOk=true;(m.mut||[]).forEach(k=>{const M=MSG_MUT[k];try{if(M&&!M.ok(t,m,plan))mutOk=false;}catch(e){}});
  /* chase detector: right after a loss, a stake more than double the plan */
  const M=(()=>{try{return ticketMoney(t)}catch(e){return null}})();const lastDone=[...m.steps].reverse().find(s=>s.done);
  const chase=!!(lastDone&&!lastDone.won&&plan&&M&&M.stake>plan*2+0.01);
  if(chase){try{const G=msgGet();msgAward(G,-50,'Chase detected: $'+M.stake.toFixed(2)+' vs planned $'+plan.toFixed(2)+' after a loss');msgSave(G);}catch(e){}
    try{alert('Heads up: this stake ($'+M.stake.toFixed(2)+') is more than double the plan ($'+plan.toFixed(2)+') right after a loss. That\'s chasing — it costs 50 XP. The plan already sizes the comeback.');}catch(e){}}
  m.steps.push({ticketId:tid,date:today(),pot:pot||0,quests:qs,rule:rc,route:rk,plannedK,actualK,plan,mutOk,chase});msSave(A);msRender();}
/* Orders for one pot: stake, legs, minimum ticket price, and the built ticket. */
function msPotOrders(m,P,routeObj){
  const r=routeObj||msParse(P.routeKey);const X=msMath(m);const L=msLegProfile(P.rule,X.R.p);const b=P.balance;
  const lanes=[];const r2=x=>Math.max(1,Math.round(x*2)/2);
  if(r.route==='twolane'){const st=Math.max(1,b*0.2);const a=r2(st*0.6),mo=r2(st*0.4);
    /* $1 minimums: on a small balance the two lanes would each round up to $1 and stake 2× the plan */
    if(a+mo>st+0.01)lanes.push({lab:'Anchor',stake:Math.min(b,r2(st)),k:2});else lanes.push({lab:'Anchor',stake:a,k:2},{lab:'Moonshot',stake:mo,k:4});}
  else lanes.push({lab:'The play',stake:Math.min(b,r2(msStakeFor(r.route,r.cfg,b,P.start))),k:r.cfg.k||2});
  return lanes.map(x=>{const minDec=barDec(Math.pow(L.dec,x.k));return{...x,minDec,build:msBuildTicket(x.k,minDec,P.rule,P.sport||m.sport||null)};});
}
function msOrders(m){ // kept for single-pot callers
  const r=msActiveRoute(m);const P=msPotsOf(m)[0];const lanes=msPotOrders(m,P,r);const cps=msCheckpoints(m);
  return{r,lanes,cps,nextCp:cps.find(c=>c.amt>m.balance+(m.safe||0)),$:x=>'$'+(Math.round(x*2)/2).toFixed(2)};
}
const ms$=x=>'$'+(+x).toFixed(2);
const MS_SP_OPTS=[['all','All sports'],['nfl','NFL only'],['ncaaf','CFB only'],['mlb','MLB only'],['nhl','NHL only']];
function msSportSelect(cur,onchange,id){return`<select ${id?`id="${id}"`:''} ${onchange?`onchange="${onchange}"`:''} style="font-size:11px;padding:4px 6px">${MS_SP_OPTS.map(([v,l])=>`<option value="${v}" ${(cur||'all')===v?'selected':''}>${l}</option>`).join('')}</select>`;}
/* Which sports Today's card has picks for right now. */
/* which sports are in season today (regular season + playoffs, by calendar) */
const SP_SEASON={mlb:['03-15','11-10'],nfl:['09-01','02-15'],ncaaf:['08-20','01-25'],nhl:['10-01','06-30'],nba:['10-18','06-25']};
/* ESPN publishes each league's calendar on its scoreboard; read it once a day.
   The hard-coded month ranges above are only the fallback. */
function spInSeason(sp,d){const day=String(d||today()).slice(0,10);
  try{const C=(get('d4.seasoncal',{})||{})[sp];if(C&&C.start&&C.end&&C.fetched>=dayShift(today(),-3))return day>=C.start&&day<=C.end;}catch(e){}
  const md=day.slice(5);const r=SP_SEASON[sp];if(!r)return true;return r[0]<=r[1]?(md>=r[0]&&md<=r[1]):(md>=r[0]||md<=r[1]);}
async function seasonCalLoad(sp){const C=get('d4.seasoncal',{})||{};if(C[sp]&&C[sp].fetched===today())return C[sp];
  try{const j=await fetch('https://site.api.espn.com/apis/site/v2/sports/'+SEASON_PATH[sp]+'/scoreboard?limit=1').then(r=>r.json());const L=(j.leagues||[])[0]||{};
    const s=L.calendarStartDate,e=L.calendarEndDate;if(s&&e){C[sp]={start:tdDay(s),end:tdDay(e),fetched:today()};set('d4.seasoncal',C);}}catch(e){}
  return C[sp]||null;}
function liveSports(){return['nfl','ncaaf','mlb','nhl','nba'].filter(sp=>spInSeason(sp));}
function tcSportsLoaded(){const T=get(TC_KEY,{})||{};const by=T.d===today()?T.by||{}:{};return['nfl','ncaaf','mlb','nhl','nba'].filter(sp=>by[sp]&&(by[sp].picks||[]).length);}
function msLaneHtml(L){const B=L.build.best;
  const legs=B?B.legs.map(x=>`<div class="mono" style="font-size:10.5px;padding-left:8px">• ${esc(x.pick)} <span style="color:var(--gold)">${x.price>0?'+':''}${x.price}</span> <span style="color:${(TC_COL[x.color]||['var(--mute)',''])[0]}">${(TC_COL[x.color]||['',''])[1]}</span>${(x.rules||[]).slice(0,1).map(r=>' '+r.icon).join('')} <span style="color:var(--mute)">${SP_LAB[x.sp]||''} ${esc(x.game)}</span></div>`).join(''):'';
  return`<div class="sub" style="margin-top:5px"><b>${L.lab}:</b> stake <b style="color:var(--gold)">${ms$(L.stake)}</b> on ${L.k===1?'a <b>single</b>':`a <b>${L.k}-team parlay</b>`} priced <b>${decimalToAmerican(L.minDec)} or longer</b> → pays ${ms$(L.stake*L.minDec)}+.</div>
    ${B?`<div class="mono" style="font-size:9.5px;color:var(--mute);margin-top:2px">Built from Today's card:</div>${legs}
      <div class="mono" style="font-size:10px;padding-left:8px;color:${B.ok?'var(--win)':'var(--rust)'}">= ${decimalToAmerican(B.d)} ${B.ok?'✓ clears the bar':'✗ short of '+decimalToAmerican(L.minDec)+' — add a leg or swap in a plus-money side'}</div>`
      :`<div class="mono" style="font-size:9.5px;color:var(--mute)">${L.build.poolN?'Not enough qualifying picks for this rule today — sit it out; skipping a day is a legal move.':'Upload today\'s lines and open a Games board — the planner builds the ticket from Today\'s card.'}</div>`}`;}
function msAfter(route,m){return{snowball:'Win → roll it all tomorrow. Miss → the run ends; run it back, never add money to chase.',
  heist:`Win → 25% of the profit goes to the safe house. Miss → the run ends${(m.safe||0)>0?`, the safe keeps ${ms$(m.safe)}`:''}.`,
  elevator:'Win → if you passed a checkpoint, half the balance goes to the safe. Miss → the run ends, the safe doesn\'t.',
  stairs:'Win or lose, tomorrow\'s stake resizes off the new balance. Never double up to chase.',
  compound:'Same % every day. The math does the work — don\'t skip ahead.',
  housemoney:'Still on your own money? The stake stays at the base. Up? The extra rides from profit only.',
  drip:'Same stake every day, win or lose, until the roll runs out or one lands.',
  twolane:'Anchor wins fund tomorrow\'s moonshot. Stakes resize from the balance.'}[route]||'';}
function msCard(m){
  const X=msMath(m);const active=m.status==='active';const col={active:'#5FD3E8',won:'var(--win)',busted:'var(--rust)',expired:'var(--mute)'}[m.status];
  const cps=msCheckpoints(m);const tot=m.balance+(m.safe||0);const T=MS_TEMPLATES[m.type]||{};
  const D=MS_DIFF.find(d=>d[1]===m.diff);
  const map=`<div style="position:relative;margin:10px 4px 20px"><div style="height:6px;background:var(--rule);border-radius:3px"><div style="height:6px;width:${Math.max(0,Math.min(100,Math.log(Math.max(1,tot/m.start))/Math.log(m.goal/m.start)*100))}%;background:${col};border-radius:3px"></div></div>
    ${cps.map((c,i)=>{const x=(i+1)/cps.length*100,hit=tot>=c.amt;return`<div style="position:absolute;left:calc(${x}% - 5px);top:-3px;width:10px;height:10px;border-radius:50%;background:${hit?col:'#1a1f27'};border:2px solid ${hit?col:'var(--mute)'}"></div>
      <div class="mono" style="position:absolute;left:calc(${x}% - 30px);width:60px;text-align:center;top:10px;font-size:7.5px;color:${hit?col:'var(--mute)'}">${c.name}<br>$${c.amt.toLocaleString()}</div>`;}).join('')}</div>`;
  const pend=get(LS.locked,[]).filter(t=>!t.archived&&!m.steps.some(s=>String(s.ticketId)===String(t.id)));
  const attach=(pot)=>`<select onchange="msAttach(${m.id},this,${pot})"><option value="">Placed it? Attach the ticket${m.pots?' to '+esc(m.pots[pot].name):''}…</option>
    ${pend.map(t=>`<option value="${esc(String(t.id))}">#${esc(String(t.id))} ${esc(t.name||'')} · ${(t.legs||[]).length} legs</option>`).join('')}</select>`;
  let orders='';
  if(active){const qs=msQuestsToday(m);const logged=m.steps.filter(s=>s.date===today()).length;
    const S=m.pots?msSimFor(m,null,1500):null;const r=m.pots?null:msActiveRoute(m);
    const potBlocks=msPotsOf(m).map((P,pi)=>{const ro=m.pots?msParse(P.routeKey):r;const lanes=msPotOrders(m,P,ro);
      const rule=P.rule?`<span class="mono" style="font-size:9px;color:#a78bfa"> · RULE: ${MS_FILTERS[P.rule].lab} (${MS_FILTERS[P.rule].desc})</span>`:'';
      const sport=P.sport?`<span class="mono" style="font-size:9px;color:#a78bfa"> · ${SPORT_LAB[P.sport]}</span>`:'';
      return`${m.pots?`<div style="margin-top:8px;padding-top:6px;border-top:1px dashed var(--rule)"><b>${esc(P.name)}</b> <span class="mono" style="font-size:10px">${ms$(P.balance)}${P.safe?` + safe ${ms$(P.safe)}`:''} · ${msRouteLabel(ro)}</span>${rule}${sport}</div>`:(rule||sport?`<div>${rule}${sport}</div>`:'')}
        ${P.balance<1?'<div class="sub" style="color:var(--rust)">This pot is spent.</div>':lanes.map(msLaneHtml).join('')}
        ${m.pots&&P.balance>=1?`<div class="bar" style="margin-top:4px">${attach(pi)}</div>`:''}`;}).join('');
    const fin=m.pots?S.p:r.p;
    orders=`<div style="margin-top:8px;padding:10px;border-radius:10px;background:rgba(95,211,232,.06);border:1px solid rgba(95,211,232,.35)">
      <div class="mono" style="font-size:9px;letter-spacing:.1em;color:#5FD3E8">TODAY'S ORDERS · DAY ${Math.min(m.days,m.days-X.daysLeft+1)} OF ${m.days}${logged?` · ✓ ${logged} STEP${logged>1?'S':''} LOGGED`:''}</div>
      <div style="font-weight:800;margin:3px 0">${m.pots?'🧺 '+m.pots.length+' pots':msRouteLabel(r)} <span class="mono" style="font-size:10px;color:var(--mute)">— ${(fin*100).toFixed(fin<0.01?2:1)}% to finish from here</span></div>
      ${(m.pots&&m.pots.every(P=>P.sport))?'':`<div class="mono" style="font-size:10px;margin:4px 0">Picks from ${msSportSelect(m.sport,`msSetSport(${m.id},this.value)`)}
        ${(()=>{const have=tcSportsLoaded(),need=m.sport?[m.sport]:liveSports();const miss=need.filter(x=>!have.includes(x));
          return miss.length?` <span style="color:var(--gold)">· Today's card has no ${miss.map(x=>SP_LAB[x]).join(', ')} picks yet</span> <a href="#" onclick="loadAllSports();return false" style="color:var(--cold)">load them</a>`:` <span style="color:var(--win)">· ${need.length>1?'all sports loaded':'loaded'}</span>`;})()}</div>`}
      ${potBlocks}
      <div class="sub" style="margin-top:6px;font-size:11px"><b>Today's threshold:</b> ${(()=>{const n=cps.find(c=>c.amt>tot);return n?`next checkpoint <b>${n.name}</b> at $${n.amt.toLocaleString()} (${ms$(n.amt-tot)} away)`:'goal in reach';})()}.</div>
      <div class="sub" style="font-size:11px"><b>After it settles:</b> ${m.pots?'each pot follows its own plan; the mission is the total.':msAfter(r.route,m)}</div>
      <div class="mono" style="font-size:9.5px;margin-top:6px;color:#FFD75E">SIDE QUESTS · ${qs.map(q=>`<b>${q.name}</b> (+${q.xp} XP): ${q.desc}`).join(' · ')}</div>
      ${m.pots?'':`<div class="bar" style="margin-top:6px">${attach(0)}</div>`}</div>
    ${m.pots?'':`<details style="margin-top:6px"><summary class="mono" style="font-size:10px">Route planner — every route simulated on ${X.R.src}</summary>
      <table class="mono" style="width:100%;font-size:9.5px;margin-top:4px;border-collapse:collapse"><tr style="color:var(--mute)"><td>route</td><td>finish</td><td>bust</td><td>med. day</td><td></td></tr>
      ${msRoutes(m).slice(0,10).map(x=>`<tr style="${msRouteKey(x)===msRouteKey(r)?'color:#5FD3E8;font-weight:700':''}"><td>${msRouteLabel(x)}</td><td>${(x.p*100).toFixed(1)}%</td><td>${Math.round(x.bust*100)}%</td><td>${x.median||'—'}</td>
        <td>${msRouteKey(x)===msRouteKey(r)?'◀':`<a href="#" onclick="msPickRoute(${m.id},'${msRouteKey(x)}');return false" style="color:var(--cold)">use</a>`}</td></tr>`).join('')}</table>
      <div class="sub" style="font-size:9.5px;color:var(--mute)">${Object.values(MS_ROUTES).map(x=>`<b>${x.name}</b>: ${x.desc}`).join('<br>')}</div></details>`}`;}
  const steps=m.steps.map((s,i)=>`<div class="mono" style="font-size:10px">Step ${i+1}${m.pots?` · ${esc(m.pots[s.pot||0].name)}`:''}: #${esc(s.ticketId)} ${s.done?(s.won?`<b style="color:var(--win)">WON</b> +${ms$(s.payout-s.stake)}`:`<b style="color:var(--rust)">LOST</b> −${ms$(s.stake)}`):'<span style="color:var(--gold)">riding…</span>'}
    ${s.rule&&!s.rule.ok?` <span style="color:var(--rust)">⚠ ${esc(s.rule.why)}</span>`:''}${(s.quests||[]).map(q=>q.done===true?` <span style="color:#FFD75E">★${q.name} +${q.xp}</span>`:q.done===false?` <span style="color:var(--mute)">✗${q.name}</span>`:` <span style="color:var(--mute)">…${q.name}</span>`).join('')}</div>`).join('');
  return`<div class="tkt" style="border-color:${col};margin:8px 0">
    <div style="display:flex;justify-content:space-between;align-items:baseline;gap:6px"><b style="font-size:14px">🎯 ${esc(m.name)}</b><span class="mono" style="font-size:10px;color:${col}">${D?`<span style="color:${D[2]}">${D[1].toUpperCase()}</span> · `:''}${m.status.toUpperCase()}${m.attempt>1?' · attempt '+m.attempt:''}</span></div>
    <div class="sub">$${m.start} → <b>$${m.goal.toLocaleString()}</b> in ${m.days} days · balance <b style="color:var(--gold)">${ms$(m.balance)}</b>${m.safe?` · safe <b style="color:var(--win)">${ms$(m.safe)}</b>`:''} · ${X.daysLeft} day${X.daysLeft>1?'s':''} left</div>
    ${m.status==='won'?`<div class="sub" style="color:var(--win)"><b>MISSION COMPLETE</b>${m.clean?' · clean run bonus':''}</div>`:''}
    ${map}${orders}<div id="msLive_${m.id}">${msLiveHtml(m)}</div>${steps}
    <div class="sub" style="font-size:10px;color:var(--mute);margin-top:4px">${esc(T.note||'')}</div>
    ${active?msAdaptHtml(m):''}${typeof msgMutHtml==='function'?msgMutHtml(m):''}
    <div class="bar" style="margin-top:4px"><button onclick="msRoadmapToggle(${m.id})">🗺 Roadmap</button>${!active?`<button onclick="msRestart(${m.id})">Run it back</button>`:''}<button onclick="msDelete(${m.id})">Delete</button></div>
    <div id="msRM_${m.id}" style="display:none"></div></div>`;
}
/* The mission board: every template with its real difficulty on your numbers. */
let MS_CAT='warmup',MS_TIER='all';const MS_BOARD_CACHE={};
function msBoardHtml(){
  const p=myLegRate().p.toFixed(3);
  const tierOf=r=>{const T=MS_TEMPLATES[r[0]];if(T.id==='custom')return null;const ck=T.id+'|'+p;let S=MS_BOARD_CACHE[ck];
    if(!S){const fake={id:7,start:T.start,goal:T.goal,days:T.days,startDate:today(),balance:T.start,safe:0,routeKey:T.route||null,rule:T.rule,
        pots:T.pots?T.pots.map(([name,share,route,rule,sport])=>({name,share,routeKey:route,rule,sport,start:T.start*share,balance:T.start*share})):null};
      try{S=MS_BOARD_CACHE[ck]=msSimFor(fake,null,700);}catch(e){return null;}}
    return msDifficulty(S.p)[1];};
  const list=MS_TIER==='all'?MS_LIB.filter(r=>r[1]===MS_CAT):MS_LIB.filter(r=>tierOf(r)===MS_TIER);
  const cards=list.map(r=>{const T=MS_TEMPLATES[r[0]];
    const ck=T.id+'|'+p;let S=MS_BOARD_CACHE[ck];
    if(!S&&T.id!=='custom'){const fake={id:7,start:T.start,goal:T.goal,days:T.days,startDate:today(),balance:T.start,safe:0,routeKey:T.route||null,rule:T.rule,
        pots:T.pots?T.pots.map(([name,share,route,rule,sport])=>({name,share,routeKey:route,rule,sport,start:T.start*share,balance:T.start*share})):null};
      try{S=MS_BOARD_CACHE[ck]=msSimFor(fake,null,700);}catch(e){S=null;}}
    const D=S?msDifficulty(S.p):null;
    const route=T.pots?'🧺 '+T.pots.map(x=>x[0]).join(' · '):T.route?msRouteLabel(msParse(T.route)):'planner picks';
    const first=T.pots?'':T.route?(()=>{const q=msParse(T.route);return' · first bet $'+Math.max(1,Math.round(Math.min(T.start,msStakeFor(q.route,q.cfg,T.start,T.start))*2)/2);})():'';
    return`<div class="tkt" style="margin:6px 0;padding:10px">
      <div style="display:flex;justify-content:space-between;gap:6px;align-items:baseline"><b>${esc(T.name)}</b>${D?`<span class="mono" style="font-size:9px;color:${D[2]}">${D[1].toUpperCase()} · ${(S.p*100).toFixed(S.p<0.01?2:1)}%</span>`:''}</div>
      <div class="mono" style="font-size:10.5px">$${T.start} → $${T.goal.toLocaleString()} · ${T.days} days${first}</div>
      <div class="mono" style="font-size:9.5px;color:var(--mute)">${route}${T.rule?' · '+MS_FILTERS[T.rule].lab:''}${T.sport?' · '+SPORT_LAB[T.sport]:''}</div>
      <div class="sub" style="font-size:11px;margin:3px 0">${esc(T.note)}</div>
      <div class="bar" style="align-items:center">${T.pots&&T.pots.every(x=>x[4])?'':msSportSelect(T.sport,'',`msSp-${T.id}`)}<button class="primary" onclick="msStart('${T.id}',(document.getElementById('msSp-${T.id}')||{}).value)">Start</button></div></div>`;}).join('');
  const tiers=`<div class="subnav" style="flex-wrap:wrap;margin-bottom:4px"><button class="${MS_TIER==='all'?'on':''}" onclick="MS_TIER='all';msRender()">By category</button>${MS_DIFF.slice().reverse().reverse().map(d=>`<button class="${MS_TIER===d[1]?'on':''}" style="color:${d[2]}" onclick="MS_TIER='${d[1]}';msRender()">${d[1]}</button>`).join('')}</div>`;
  const cats=MS_TIER==='all'?`<div class="subnav" style="flex-wrap:wrap">${Object.entries(MS_CATS).map(([k,l])=>`<button class="${MS_CAT===k?'on':''}" onclick="MS_CAT='${k}';msRender()">${l}</button>`).join('')}</div>`:
    `<div class="sub mono" style="font-size:9.5px;color:var(--mute);margin:2px 0">${list.length} ${MS_TIER} mission${list.length===1?'':'s'} across every category${list.length?'':' — as your record improves, missions move into easier tiers'}</div>`;
  return tiers+cats+cards;
}
function missionsHtml(inner){
  const A=msSync();const xp=msXP(),R=msRank(xp);const act=A.filter(m=>m.status==='active');
  let exposure=0;act.forEach(m=>{try{msPotsOf(m).forEach(P=>{if(P.balance<1)return;msPotOrders(m,P,m.pots?null:msActiveRoute(m)).forEach(L=>exposure+=L.stake);});}catch(e){}});
  const head=`<div class="mono" style="font-size:10.5px;margin:2px 0 6px">RANK <b style="color:#FFD75E">${R.name.toUpperCase()}</b> · ${xp} XP${R.next?` · ${R.next[0]-xp} to ${R.next[1]}`:''}${act.length?` · ${act.length} running · today's stakes across missions <b style="color:var(--gold)">${ms$(exposure)}</b>`:''}</div>`;
  const hub=(()=>{try{return msgHubHtml()}catch(e){console.warn('game hub',e);return''}})();
  const body=`${head}${hub}<div class="lasStatus sub mono" style="font-size:10px"></div>${A.length?A.map(msCard).join(''):'<div class="empty">No missions running. Pick one below — the planner does the math and writes your orders every day.</div>'}
    <div class="sbar" style="margin-top:12px"><h2>Mission board · ${MS_LIB.length}</h2><div class="ln"></div></div>
    <div class="sub mono" style="font-size:9.5px;color:var(--mute)">Difficulty and finish % are simulated on ${myLegRate().src}. They move as your record grows.</div>
    ${msBoardHtml()}`;
  return inner?body:`<div class="sbar"><h2>Missions</h2><div class="ln"></div></div><div id="missionsBody">${body}</div>`;
}

/* ══ PROP BACKTRACK ══════════════════════════════════════════════════════════
   Grades every player-prop leg on every ticket — pending and archived — by
   pulling each game's final box score from ESPN once and saving it for good.
   Runs by itself once a day when Tickets or My Games opens and something is
   still ungraded; the "Regrade props" button runs it on demand. */
let BT_BUSY=false;
function btPropLegs(){
  const out=[];get(LS.locked,[]).forEach(t=>(t.legs||[]).forEach(l=>{if(!l.fbProp&&!l.nhlProp&&!l.mlbProp)return;
    const sp=l.nhlProp?'nhl':l.mlbProp?'mlb':(l.sport==='ncaaf'?'ncaaf':'nfl');out.push({t,l,sp});}));return out;
}
let BT_UG=null;
function btUngraded(){if(BT_UG&&Date.now()-BT_UG.ts<5000)return BT_UG.v;const v=btUngradedCore();BT_UG={ts:Date.now(),v};return v;}
function btUngradedCore(){return btPropLegs().filter(x=>{let g=null;try{g=gradeLeg(x.l,x.t.date)}catch(e){}return!g||(g.hit==null&&!g.live&&!g.push);});}
async function btWaitId(leg,date,tries){for(let i=0;i<(tries||30);i++){const ev=fbpEventId(leg,date);if(ev.id)return ev.id;if(!ev.pending&&i>0)return null;await new Promise(r=>setTimeout(r,350));}return null;}
async function regradeAllProps(statusEl){
  if(BT_BUSY)return;BT_BUSY=true;const say=h=>{const e=statusEl||document.getElementById('btStatus');if(e)e.innerHTML=h;};
  try{
    BT_UG=null;const todo=btUngraded();if(!todo.length){say('<span style="color:var(--win)">✓ Every prop leg is graded.</span>');return{legs:0,games:0};}
    try{const T=get('d4.fbptried',{})||{};Object.keys(T).forEach(k=>delete T[k]);set('d4.fbptried',T);}catch(e){}   // give ESPN a fresh try
    const ev={};let n=0;
    for(const x of todo){n++;say(`Finding games… ${n}/${todo.length}`);
      const id=await btWaitId({...x.l,sport:x.sp},x.t.date);if(id)(ev[x.sp+':'+id]=ev[x.sp+':'+id]||{sp:x.sp,id});}
    const games=Object.values(ev);let g=0;
    const S=get(FBP_BOX_KEY,{})||{};
    for(const G of games){g++;say(`Pulling box scores… ${g}/${games.length}`);
      if(S[G.sp+':'+G.id]&&S[G.sp+':'+G.id].final)continue;
      try{const r=await fetch(FBP_ESPN[G.sp]+'/summary?event='+G.id);const j=await r.json();
        const box=G.sp==='nhl'?fbpParseHockey(j):G.sp==='mlb'?fbpParseBaseball(j):fbpParseBox(j);FBP_MEM[G.id]={ts:Date.now(),box};
        if(box.state==='post'){const A=get(FBP_BOX_KEY,{})||{};A[G.sp+':'+G.id]={ts:Date.now(),final:true,box};set(FBP_BOX_KEY,A);}}catch(e){}
      await new Promise(r=>setTimeout(r,200));}
    BT_UG=null;const left=btUngraded().length,done=todo.length-left;
    set('d4.btDay',today());
    say(`<span style="color:${left?'var(--gold)':'var(--win)'}">✓ ${done} prop leg${done===1?'':'s'} graded from ${games.length} box score${games.length===1?'':'s'}${left?` · ${left} still waiting (game not final yet, or the player isn't in ESPN's box — check the name)`:''}.</span>`);
    try{if(typeof renderTickets==='function'&&document.getElementById('tickets'))renderTickets();}catch(e){}
    try{const v=document.getElementById('v-mine');if(v&&v.classList.contains('on'))renderMyGames();}catch(e){}
    try{msSync();}catch(e){}
    return{legs:done,games:games.length,left};
  }finally{BT_BUSY=false;}
}
function btAutoOnce(){if(typeof BG_MODE!=='undefined'&&BG_MODE)return;try{if(get('d4.btDay','')===today())return;const past=btUngraded().filter(x=>String(x.l.gameDate||x.t.date).slice(0,10)<today());
  if(past.length)setTimeout(()=>regradeAllProps(),800);}catch(e){}}
function btBarHtml(){return`<div class="bar" style="margin:6px 0"><button onclick="regradeAllProps()">↻ Regrade props (pull final box scores)</button></div><div id="btStatus" class="sub mono" style="font-size:10px"></div>`;}


/* ══ LOAD ALL SPORTS ═════════════════════════════════════════════════════════
   Today's card only knows a sport once its board has run today. This loads
   each missing sport's page in a hidden frame, one at a time, lets its board
   render (which files that sport's picks into Today's card), then closes it.
   Your current sport choice is saved first and put back after. */
const BG_MODE=typeof location!=='undefined'&&/[?&]bg=1/.test(location.search||'');
let LAS_BUSY=false;
async function loadAllSports(opts){
  if(LAS_BUSY||BG_MODE)return;LAS_BUSY=true;opts=opts||{};
  const say=h=>{document.querySelectorAll('.lasStatus').forEach(e=>e.innerHTML=h);};
  const keep=(()=>{try{return localStorage.getItem('d4.activeSport')}catch(e){return null}})();
  const here=window.__PAGE_SPORT__||ACTIVE_SPORT;
  const todo=(opts.sports||liveSports()).filter(sp=>sp!==here&&(opts.force||!tcSportsLoaded().includes(sp)));
  try{
    try{todaySnapshot()}catch(e){}
    for(const sp of todo){
      say(`Loading ${SP_LAB[sp]} board in the background…`);
      const t0=Date.now();const f=document.createElement('iframe');
      f.src=SPORT_PAGE[sp]+'?bg=1';f.setAttribute('aria-hidden','true');f.style.cssText='position:absolute;width:1px;height:1px;left:-9999px;border:0;opacity:0';
      document.body.appendChild(f);
      const got=await new Promise(res=>{const iv=setInterval(()=>{const T=get(TC_KEY,{})||{};const B=T.d===today()&&T.by&&T.by[sp];
        if(B&&B.ts>=t0){clearInterval(iv);res(true);}else if(Date.now()-t0>(opts.timeout||45000)){clearInterval(iv);res(false);}},500);});
      try{f.remove()}catch(e){}
      try{if(keep!=null)localStorage.setItem('d4.activeSport',keep)}catch(e){}
      if(!got)say(`${SP_LAB[sp]} didn't finish loading — try that board directly.`);
    }
    const have=tcSportsLoaded();
    say(`<span style="color:var(--win)">✓ Today's card: ${have.length?have.map(x=>SP_LAB[x]).join(' · '):'no picks yet (upload today\'s lines first)'}</span>`);
    try{const v=document.getElementById('v-today');if(v&&v.classList.contains('on'))renderToday(true);}catch(e){}
    try{msRender()}catch(e){}
  }finally{LAS_BUSY=false;try{if(keep!=null)localStorage.setItem('d4.activeSport',keep)}catch(e){}}
}

/* ══ SHARP LAYER ═════════════════════════════════════════════════════════════
   What the betting-market literature agrees on, built into the app:
   1  a sharp reference price (Pinnacle) to judge every soft-book line
   2  closing-line value measured against the SHARP close
   3  parlay/SGP odds with the correlation between legs included
   4  margin removal that respects the favorite-longshot bias (power method)
   5  model + market blended, weighted by which has predicted better for you
   6  calibration and luck-vs-skill on the records
   7  a haircut on data-mined trends (in brainTrendEvidence)
   8  risk-of-ruin and correlated stake sizing
   9  line-movement and reverse-line-movement alerts                          */

/* ── 4. Power devig: favorites carry less of the book's margin than longshots ── */
function devigPower(a,b){ // a,b = implied probabilities WITH the book's margin
  if(!(a>0&&b>0))return null;if(a+b<=1.0005)return[a/(a+b),b/(a+b)];
  let lo=1,hi=5;for(let i=0;i<50;i++){const k=(lo+hi)/2;const s=Math.pow(a,k)+Math.pow(b,k);if(s>1)lo=k;else hi=k;}
  const k=(lo+hi)/2;const fa=Math.pow(a,k),fb=Math.pow(b,k);return[fa/(fa+fb),fb/(fa+fb)];
}
function fairPair(pa,pb){const a=amerOk(pa),b=amerOk(pb);if(a==null||b==null)return null;return devigPower(imp(a),imp(b));}

/* ── 1. Sharp reference lines from Pinnacle via your Odds API key ── */
const SHARP_KEY='d4.sharpref';
const ODDS_SPORT={mlb:'baseball_mlb',nfl:'americanfootball_nfl',ncaaf:'americanfootball_ncaaf',nhl:'icehockey_nhl'};
function sharpStore(){return roGet(SHARP_KEY,{},15e3)||{};}
async function pullSharp(sports){
  const key=typeof theOddsApiKey==='function'?theOddsApiKey():get(LS.key,'');if(!key)throw new Error('add your Odds API key in Settings first');
  const all=get(SHARP_KEY,{})||{};let n=0;const done=[];
  for(const sp of sports||['mlb','nfl','ncaaf','nhl','nba']){
    let j;try{const r=await fetch(`https://api.the-odds-api.com/v4/sports/${ODDS_SPORT[sp]}/odds/?apiKey=${key}&regions=eu&bookmakers=pinnacle&markets=h2h,spreads,totals&oddsFormat=american`);
      if(r.status===401)throw new Error('Odds API 401 — bad key or out of credits');j=await r.json();}catch(e){if(/401/.test(e.message))throw e;continue;}
    if(!Array.isArray(j))continue;
    j.forEach(ev=>{const a=intakeAbbr(sp,ev.away_team),h=intakeAbbr(sp,ev.home_team);if(!a||!h)return;const gl=a+'@'+h;
      const d=new Intl.DateTimeFormat('en-CA',{timeZone:APP_TZ,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(ev.commence_time));
      const bk=(ev.bookmakers||[]).find(b=>b.key==='pinnacle');if(!bk)return;
      const D=((all[d]=all[d]||{})[sp]=(all[d]&&all[d][sp])||{ts:0,rows:[]});
      D.rows=D.rows.filter(x=>x.game!==gl);
      (bk.markets||[]).forEach(mk=>(mk.outcomes||[]).forEach(o=>{
        const side=mk.key==='totals'?(/over/i.test(o.name)?'over':'under'):(intakeAbbr(sp,o.name)===a?'away':'home');
        const market=mk.key==='h2h'?'ml':mk.key==='spreads'?'spread':'total';
        if(amerOk(o.price)==null)return;D.rows.push({game:gl,market,side,line:o.point!=null?+o.point:null,price:amerOk(o.price),ts:Date.now()});n++;}));
      D.ts=Date.now();});
    done.push(sp);
  }
  Object.keys(all).sort().slice(0,-4).forEach(k=>delete all[k]);
  set(SHARP_KEY,all);try{Object.keys(CHAR_CACHE).forEach(k=>delete CHAR_CACHE[k]);}catch(e){}try{['mlb','nfl','ncaaf','nhl','nba'].forEach(sp=>clvCapture(sp));}catch(e){}
  return{n,sports:done};
}
function sharpRows(sp,gl,date){const D=((sharpStore()[date||today()]||{})[sp]);return D?D.rows.filter(x=>x.game===gl):[];}
/* Fair (no-vig) chance of one side at one line, from the sharp book. */
function sharpFair(sp,gl,market,side,line,date){
  const R=sharpRows(sp,gl,date);if(!R.length)return null;
  const other={away:'home',home:'away',over:'under',under:'over'}[side];
  const me=R.find(x=>x.market===market&&x.side===side&&(market==='ml'||x.line===line));
  const op=R.find(x=>x.market===market&&x.side===other&&(market==='ml'||(market==='spread'?x.line===-line:x.line===line)));
  if(!me||!op)return null;const f=fairPair(me.price,op.price);return f?{p:f[0],price:me.price,line:me.line}:null;
}
/* The market's fair chance for a square: the sharp price when we have it, else your book's two sides. */
function marketFair(sp,g,market,side,line){
  const gl=g.away.abbr+'@'+g.home.abbr;const S=sharpFair(sp,gl,market,side,line);if(S)return{p:S.p,src:'sharp'};
  try{const Ln=voicesLines(sp,g);const pick=(m,s)=>m==='ml'?(s==='home'?Ln.mlH:Ln.mlA):m==='spread'?(s==='home'?Ln.spH:Ln.spA):(s==='over'?Ln.ov:Ln.un);
    const me=pick(market,side),op=pick(market,{away:'home',home:'away',over:'under',under:'over'}[side]);
    if(me&&op){const f=fairPair(me.price,op.price);if(f)return{p:f[0],src:'book'};}}catch(e){}
  return null;
}

/* ── 5. Model + market blend, weighted by what has actually predicted better ── */
let BLEND_C=null,BLEND_SIG='';
function blendWeight(sp,market){
  const V=roGet(VOICES_KEY,[]);const sig=V.length;if(!BLEND_C||BLEND_SIG!==sig){BLEND_C={};BLEND_SIG=sig;}
  const k=sp+'|'+market;if(BLEND_C[k])return BLEND_C[k];
  const R=V.filter(x=>x.voice==='Sim'&&x.sp===sp&&x.market===market&&x.graded&&x.hit!=null&&x.simP>0&&x.mktP>0);
  let best=0.5,bestB=Infinity;
  for(let w=0;w<=1.0001;w+=0.05){let b=0;R.forEach(x=>{const p=w*x.simP+(1-w)*x.mktP;b+=Math.pow((x.hit?1:0)-p,2);});if(R.length&&b<bestB){bestB=b;best=w;}}
  const n=R.length;const w=(n*best+25*0.5)/(n+25);   // few graded games → stay near an even blend
  return(BLEND_C[k]={w,n});
}
function blendProb(sp,market,simP,mktP){if(simP==null)return null;if(mktP==null)return simP;const {w}=blendWeight(sp,market);return w*simP+(1-w)*mktP;}

/* ── 3. Correlated parlay odds: legs from the same game move together ── */
function sjRng(seed){let a=seed>>>0;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function sjPois(l,r){const L=Math.exp(-l);let k=0,p=1;do{k++;p*=r();}while(p>L);return k-1;}
function sjNB(mu,disp,r){const g=(sh)=>{let d=sh-1/3,c=1/Math.sqrt(9*d);for(;;){let x,v;do{const u1=r(),u2=r();x=Math.sqrt(-2*Math.log(u1||1e-9))*Math.cos(2*Math.PI*u2);v=1+c*x;}while(v<=0);v=v*v*v;const u=r();if(u<1-0.0331*x*x*x*x||Math.log(u)<0.5*x*x+d*(1-v+Math.log(v)))return d*v;}};
  return sjPois(g(disp)*mu/disp,r);}
function sjNorm(r){return Math.sqrt(-2*Math.log(r()||1e-9))*Math.cos(2*Math.PI*r());}
/* Scores drawn around the sim's own projections, so the marginals match the app and the legs share each draw. */
function gameDraws(sp,s,N,seed){
  const r=sjRng(seed||1);const out=[];
  const mA=sp==='mlb'?s.aR:s.awayProj,mH=sp==='mlb'?s.hR:s.homeProj;if(!(mA>0&&mH>0))return null;
  for(let i=0;i<(N||4000);i++){let a,h;
    if(sp==='nhl'){a=sjPois(mA,r);h=sjPois(mH,r);if(a===h){if(r()<mH/(mA+mH))h++;else a++;}}
    else if(sp==='mlb'){a=sjNB(mA,4,r);h=sjNB(mH,4,r);while(a===h){if(r()<0.5)a++;else h++;}}
    else{const sd=sp==='nfl'?9.6:11.5;a=Math.max(0,Math.round(mA+sd*sjNorm(r)));h=Math.max(0,Math.round(mH+sd*sjNorm(r)));if(a===h){if(r()<0.5)a+=3;else h+=3;}}
    out.push([a,h]);}
  return out;
}
function legTest(sp,g,pick){
  const k=sqKey(sp,g,pick);if(!k)return null;const n=+((String(pick).match(/([+-]?\d+(?:\.\d+)?)\s*$/)||[])[1]);
  if(k.market==='ml')return([a,h])=>k.side==='home'?h>a:a>h;
  if(k.market==='total'&&!isNaN(n))return([a,h])=>k.side==='over'?a+h>n:a+h<n;   // a push counts as a miss here (conservative)
  if(k.market==='spread'&&!isNaN(n))return([a,h])=>(k.side==='home'?h-a:a-h)+n>0;
  return null;
}
function parlayCorrelation(t){
  const legs=t.legs||[];if(legs.length<2)return null;const byG={};
  legs.forEach(l=>{const sp=l.sport||'mlb';(byG[sp+'|'+l.game]=byG[sp+'|'+l.game]||{sp,game:l.game,legs:[]}).legs.push(l);});
  let indep=1,joint=1,modeled=0,groups=[];
  Object.values(byG).forEach((G,gi)=>{
    const g=sportGames(G.sp).find(z=>z.away.abbr+'@'+z.home.abbr===G.game);const s=g?(sportSims(G.sp)[g.id]||(G.sp==='nhl'&&typeof nhlSimFor==='function'?nhlSimFor(g):null)):null;
    const tests=g?G.legs.map(l=>legTest(G.sp,g,l.pick)):[];
    const D=s&&tests.length&&tests.every(Boolean)?gameDraws(G.sp,s,4000,gi+7):null;
    if(D&&G.legs.length>=1){const ps=tests.map(f=>D.filter(f).length/D.length);const pj=D.filter(d=>tests.every(f=>f(d))).length/D.length;
      const pi=ps.reduce((x,y)=>x*y,1);indep*=pi;joint*=pj;modeled+=G.legs.length;if(G.legs.length>1)groups.push({game:G.game,n:G.legs.length,ratio:pi>0?pj/pi:null});}
    else G.legs.forEach(l=>{const p=l.price!=null&&amerOk(l.price)!=null?imp(amerOk(l.price))*0.955:(l.p>0&&l.p<1?l.p:0.5);indep*=p;joint*=p;});
  });
  return{indep,joint,modeled,total:legs.length,groups};
}
function parlayCorrHtml(t){
  const C=parlayCorrelation(t);if(!C||!C.groups.length)return'';
  const M=ticketMoney(t);const bookP=M?M.stake/M.payout:null;
  const fmt=p=>p>0?'1 in '+Math.round(1/p).toLocaleString():'—';
  const g=C.groups.map(x=>`${esc(x.game)} ×${x.n}: ${x.ratio>=1.05?'legs help each other':x.ratio<=0.95?'legs work against each other':'about independent'} (${x.ratio?x.ratio.toFixed(2):'—'}×)`).join('<br>');
  const verdict=bookP?(C.joint>bookP*1.05?`<b style="color:var(--win)">priced long — correlation is on your side</b>`:C.joint<bookP*0.95?`<b style="color:var(--rust)">priced short for how these legs move together</b>`:'priced about fair'):'';
  return`<div class="mono" style="margin-top:5px;font-size:10px;line-height:1.55;color:var(--chalk)">🔗 <b>Same-game legs</b> — true chance ${fmt(C.joint)} vs ${fmt(C.indep)} if independent${bookP?` · book pays like ${fmt(bookP)}`:''}${verdict?' · '+verdict:''}<br><span style="color:var(--mute)">${g}${C.modeled<C.total?` · ${C.total-C.modeled} leg(s) off this page's slate counted as independent`:''}</span></div>`;
}

/* ── 6. Calibration + luck vs skill ── */
function normCdf(z){const t=1/(1+0.2316419*Math.abs(z));const d=0.3989423*Math.exp(-z*z/2);const p=d*t*(0.3193815+t*(-0.3565638+t*(1.781478+t*(-1.821256+t*1.330274))));return z>0?1-p:p;}
function luckSkill(w,n,p0){if(n<5)return{lab:'too few to judge',p:null};p0=p0||0.524;const z=(w-n*p0)/Math.sqrt(n*p0*(1-p0));const p=1-normCdf(z);
  return{z,p,lab:z<=0?'below breakeven':p<0.05?'strong sign of skill':p<0.2?'leaning skill':'could easily be luck'};}
/* ══ SITUATIONAL FACTORS — handicapping knowledge the brain must PROVE ═════
   Every Sim call is tagged at lock time with the situations it sits in.
   After grading, each factor's real hit rate is compared with what the model
   said. A factor only moves future probabilities once the evidence is real:
   30+ graded calls, |z| ≥ 1.5, the measured gap shrunk toward zero (K=60),
   each factor capped at ±2.5 pts and the total at ±4 pts. Markets already
   price most of this (published work on NBA back-to-backs and NFL rest says
   blind fades don't beat the spread) — so nothing is assumed; it's learned.
   Sources for the factor list: key-number frequencies (3, 7 dominate NFL
   margins; a half point onto 3 is worth ~4 pts of win probability on
   Pinnacle's ladder vs ~1.5 elsewhere), the favorite–longshot bias,
   rest/back-to-back fatigue research, and Pythagorean luck regression.   */
const FAC_LAB={fav:'favorite',bigfav:'big favorite (-200 or shorter)',dog:'underdog',longdog:'long underdog (+200 or longer)',home:'home side',road:'road side',
  key3:'spread on the 3 (2.5–3.5)',key7:'spread on the 7 (6.5–7.5)',bigline:'big spread (10+)',over:'over',under:'under',hitot:'high total',lotot:'low total',
  b2b:'picked team on 2nd night of back-to-back',oppb2b:'opponent on back-to-back',restedge:'picked team rested, opponent on back-to-back',
  pythlucky:'picked team over-performing its scoring (Pythagorean)',pythunlucky:'picked team under-performing its scoring (Pythagorean)'};
const FAC_HI={nfl:48,ncaaf:58,nba:232,mlb:9.5,nhl:6.5},FAC_LO={nfl:40,ncaaf:45,nba:215,mlb:7.5,nhl:5.5};
const FAC_PYTH={mlb:1.83,nfl:2.37,ncaaf:2.37,nhl:2.05,nba:13.91};
/* one index over the finals store per update (not a full scan per square) */
let FAC_IDX=null,FAC_IDX_SRC=null;
function facIndex(){const F=allFinals();if(FAC_IDX&&FAC_IDX_SRC===F)return FAC_IDX;const I={};
  Object.keys(F).forEach(k=>{const i=k.indexOf(':');const sp=k.slice(0,i),[a,h]=k.slice(i+1).split('@');const E=F[k];const S=I[sp]||(I[sp]={day:{},agg:{}});
    if(E.d){const D=S.day[E.d]||(S.day[E.d]=new Set());D.add(a);D.add(h);}
    [[a,+E.a,+E.h],[h,+E.h,+E.a]].forEach(([t,me,op])=>{if(!isFinite(me)||!isFinite(op))return;const o=S.agg[t]||(S.agg[t]={w:0,n:0,pf:0,pa:0});o.n++;o.pf+=me;o.pa+=op;if(me>op)o.w++;});});
  FAC_IDX=I;FAC_IDX_SRC=F;return I;}
function facPlayedOn(sp,team,day){try{const S=facIndex()[sp];return!!(S&&S.day[day]&&S.day[day].has(team));}catch(e){return false;}}
/* Pythagorean luck from the brain's own season ledger of finals */
/* Full-season W/L and points for/against from ESPN standings — once a day per sport.
   Field names differ by sport (NHL "points" are standings points, not goals), so
   each candidate field is accepted only if its per-game value is a sane score. */
const SEASON_PATH={mlb:'baseball/mlb',nfl:'football/nfl',ncaaf:'football/college-football',nhl:'hockey/nhl',nba:'basketball/nba'};
const SEASON_RANGE={mlb:[2,8],nfl:[10,40],ncaaf:[8,55],nhl:[1.5,5],nba:[85,135]};
function seasonParse(sp,j){const teams={};const R=SEASON_RANGE[sp];
  const walk=n=>{(n.children||[]).forEach(walk);((n.standings||{}).entries||[]).forEach(e=>{const ab=e.team&&e.team.abbreviation;if(!ab)return;
    const st=k=>{const s=(e.stats||[]).find(x=>x.name===k||x.type===k);return s&&isFinite(+s.value)?+s.value:null;};
    const w=st('wins'),l=st('losses'),gp=st('gamesPlayed')||((w||0)+(l||0)+(st('ties')||0)+(st('otLosses')||st('OTLosses')||0));if(!gp)return;
    const pick=c=>{for(const k of c){const v=st(k);if(v!=null&&v/gp>=R[0]&&v/gp<=R[1])return v;}return null;};
    const pf=pick(['goalsFor','runsScored','runs','pointsFor']),pa=pick(['goalsAgainst','runsAllowed','pointsAgainst']);
    if(pf!=null&&pa!=null&&w!=null)teams[ab]={w,l:l||0,gp,pf,pa};});};
  walk(j||{});return teams;}
async function seasonStatsLoad(sp,force){const S=get('d4.seasonstats',{})||{};if(!force&&S[sp]&&S[sp].d===today())return S[sp].teams;
  const y=new Date().getFullYear();const url='https://site.api.espn.com/apis/v2/sports/'+SEASON_PATH[sp]+'/standings'+(sp==='ncaaf'?'?group=80':'');
  try{const j=await fetch(url).then(r=>r.json());const teams=seasonParse(sp,j);if(Object.keys(teams).length){S[sp]={d:today(),teams};set('d4.seasonstats',S);}return teams;}catch(e){return(S[sp]||{}).teams||{};}}
function seasonTeam(sp,team){const S=get('d4.seasonstats',{})||{};return((S[sp]||{}).teams||{})[team]||null;}
if(typeof window!=='undefined')window.addEventListener('load',()=>setTimeout(async()=>{try{for(const sp of Object.keys(SEASON_PATH))await seasonCalLoad(sp);liveSports().forEach(sp=>seasonStatsLoad(sp));}catch(e){}},6000));
function facPyth(sp,team){const T=seasonTeam(sp,team);
  if(T&&T.gp>=8&&T.pf>0&&T.pa>0){const x=FAC_PYTH[sp]||2;const exp=Math.pow(T.pf,x)/(Math.pow(T.pf,x)+Math.pow(T.pa,x));return{actual:T.w/T.gp,exp,n:T.gp,src:'season'};}
  try{const S=facIndex()[sp];const o=S&&S.agg[team];if(!o||o.n<10||o.pf<=0||o.pa<=0)return null;const x=FAC_PYTH[sp]||2;
    const exp=Math.pow(o.pf,x)/(Math.pow(o.pf,x)+Math.pow(o.pa,x));return{actual:o.w/o.n,exp,n:o.n};}catch(e){return null;}}
function factorsFor(sp,g,c){const f=[];const side=c.sd||c.side,m=c.m||c.market,line=c.line!=null?+c.line:null,price=c.price!=null?+c.price:null;
  const team=side==='home'?g.home.abbr:side==='away'?g.away.abbr:null,opp=side==='home'?g.away.abbr:side==='away'?g.home.abbr:null;
  if(m==='ml'||m==='moneyline'){if(price!=null){f.push(price<0?'fav':'dog');if(price<=-200)f.push('bigfav');if(price>=200)f.push('longdog');}}
  if(team)f.push(side==='home'?'home':'road');
  if((m==='spread')&&line!=null){const a=Math.abs(line);if(sp==='nfl'||sp==='ncaaf'){if(a>=2.5&&a<=3.5)f.push('key3');if(a>=6.5&&a<=7.5)f.push('key7');}if(a>=10)f.push('bigline');}
  if(m==='total'&&line!=null){f.push(side==='over'?'over':'under');if(line>=(FAC_HI[sp]||1e9))f.push('hitot');if(line<=(FAC_LO[sp]||-1))f.push('lotot');}
  if(team&&(sp==='nba'||sp==='nhl')){const y=dayShift(gameDayOf(g)||today(),-1);const tb=facPlayedOn(sp,team,y),ob=facPlayedOn(sp,opp,y);
    if(tb)f.push('b2b');if(ob)f.push('oppb2b');if(ob&&!tb)f.push('restedge');}
  if(team){const P=facPyth(sp,team);if(P){if(P.actual-P.exp>=0.08)f.push('pythlucky');if(P.exp-P.actual>=0.08)f.push('pythunlucky');}}
  return f;}
let FAC_C=null,FAC_SIG='';
function factorTable(sp){const V=roGet(VOICES_KEY,[]);const sig=V.length+'|'+V.filter(x=>x.graded).length;if(!FAC_C||FAC_SIG!==sig){FAC_C={};FAC_SIG=sig;}
  if(FAC_C[sp])return FAC_C[sp];const T={};
  V.forEach(x=>{if(x.sp!==sp||x.voice!=='Sim'||!x.graded||x.hit==null||!(x.simP>0)||!Array.isArray(x.f))return;const p=x.pUsed!=null?x.pUsed:x.simP;
    x.f.forEach(k=>{const o=T[k]||(T[k]={n:0,w:0,ps:0,vs:0});o.n++;if(x.hit)o.w++;o.ps+=p;o.vs+=p*(1-p);});});
  Object.entries(T).forEach(([k,o])=>{o.rate=o.w/o.n;o.pred=o.ps/o.n;o.gap=o.rate-o.pred;o.z=o.vs>0?(o.w-o.ps)/Math.sqrt(o.vs):0;
    o.adj=(o.n>=30&&Math.abs(o.z)>=1.5)?Math.max(-0.025,Math.min(0.025,o.gap*o.n/(o.n+60))):0;});
  return(FAC_C[sp]=T);}
function factorAdj(sp,fs){if(!fs||!fs.length)return 0;const T=factorTable(sp);const a=fs.reduce((s,k)=>s+((T[k]||{}).adj||0),0);return Math.max(-0.04,Math.min(0.04,a));}
function factorHtml(sp){const T=factorTable(sp);const rows=Object.entries(T).sort((a,b)=>b[1].n-a[1].n).map(([k,o])=>
  `<tr><td style="text-align:left">${esc(FAC_LAB[k]||k)}</td><td>${o.n}</td><td>${Math.round(o.pred*100)}%</td><td>${Math.round(o.rate*100)}%</td><td style="color:${o.adj?'var(--gold)':'var(--mute)'}">${o.adj?(o.adj>0?'+':'')+(o.adj*100).toFixed(1)+' pts':o.n<30?'needs '+(30-o.n)+' more':'not significant'}</td></tr>`).join('');
  if(!rows)return'';return`<div style="overflow-x:auto;margin-top:6px"><div class="sub" style="font-size:9.5px"><b>Situations the brain is testing</b> — it only adjusts once a pattern is statistically real (30+ games, z ≥ 1.5), and never by more than 4 pts.</div>
  <table class="mono" style="width:100%;font-size:10px;text-align:center"><tr style="color:var(--mute)"><td style="text-align:left">situation</td><td>n</td><td>model said</td><td>won</td><td>learned adj</td></tr>${rows}</table></div>`;}
/* ══ CALIBRATION — shown per sport, day by day, with the reasons ══════════
   "Calibrated" means when the Sim says 60%, it wins ~60%. Three numbers:
   · Brier: mean squared error of the probability (0.25 = coin flip, lower = better)
   · Gap (ECE): average distance between stated % and actual win rate, per bucket
   · Blend: how much the model trusts its Sim vs the market, re-fit on graded
     results (search 0..1 for the weight with the lowest Brier, shrunk toward
     50/50 until there are enough games). A daily snapshot lets it explain
     what moved and why.                                                     */
const CAL_HIST='d4.calhist',CAL_SPS=['mlb','nfl','ncaaf','nhl','nba'];
const CAL_LAB={mlb:'⚾ MLB',nfl:'🏈 NFL',ncaaf:'🏟 CFB',nhl:'🏒 NHL',nba:'🏀 NBA'};
function calRows(){return roGet(VOICES_KEY,[]).filter(x=>x.voice==='Sim'&&x.graded&&x.hit!=null&&x.simP>0);}
const calBrier=(R,f)=>R.length?R.reduce((a,x)=>a+Math.pow((x.hit?1:0)-f(x),2),0)/R.length:null;
function calECE(R){if(!R.length)return null;const B={};R.forEach(x=>{const k=Math.min(9,Math.floor(x.simP*10));(B[k]=B[k]||[]).push(x);});
  return Object.values(B).reduce((a,b)=>a+b.length*Math.abs(b.filter(x=>x.hit).length/b.length-b.reduce((s,x)=>s+x.simP,0)/b.length),0)/R.length;}
function calTable(R){const bins=[[0.5,0.55],[0.55,0.6],[0.6,0.65],[0.65,0.7],[0.7,0.8],[0.8,1.01],[0,0.5]];
  const rows=bins.map(([lo,hi])=>{const B=R.filter(x=>x.simP>=lo&&x.simP<hi);if(!B.length)return'';const pr=B.reduce((a,x)=>a+x.simP,0)/B.length,ac=B.filter(x=>x.hit).length/B.length,off=(ac-pr)*100;
    return`<tr><td>${lo===0?'<50%':Math.round(lo*100)+'–'+Math.min(100,Math.round(hi*100))+'%'}</td><td>${Math.round(pr*100)}%</td><td style="color:${Math.abs(off)<5?'var(--win)':off>0?'var(--cold)':'var(--rust)'}">${Math.round(ac*100)}%</td><td>${off>=0?'+':''}${off.toFixed(0)}</td><td>${B.length}</td></tr>`;}).join('');
  return`<table class="mono" style="width:100%;font-size:10px;text-align:center"><tr style="color:var(--mute)"><td>Sim said</td><td>avg</td><td>actually won</td><td>off</td><td>n</td></tr>${rows}</table>`;}
/* daily snapshot of what the model believes, per sport (one per day) */
function calSnapshot(){const H=get(CAL_HIST,{})||{};const d=today();if(H[d])return H;const R=calRows();H[d]={};
  CAL_SPS.forEach(sp=>{const S=R.filter(x=>x.sp===sp);if(!S.length)return;const bw={};['ml','spread','total'].forEach(m=>{try{bw[m]=blendWeight(sp,m);}catch(e){}});
    H[d][sp]={n:S.length,brier:calBrier(S,x=>x.simP),ece:calECE(S),bw};});
  Object.keys(H).sort().slice(0,-90).forEach(k=>delete H[k]);set(CAL_HIST,H);return H;}
function calWhy(sp){const H=get(CAL_HIST,{})||{};const days=Object.keys(H).filter(d=>H[d][sp]).sort();if(days.length<2)return'';
  const now=H[days[days.length-1]][sp],then=H[days[Math.max(0,days.length-8)]][sp];const out=[];
  ['ml','spread','total'].forEach(m=>{const a=(then.bw||{})[m],b=(now.bw||{})[m];if(!a||!b)return;const dw=b.w-a.w;if(Math.abs(dw)<0.02)return;
    const R=calRows().filter(x=>x.sp===sp&&x.market===m&&x.mktP>0);const bs=calBrier(R,x=>x.simP),bm=calBrier(R,x=>x.mktP);
    out.push(`<b>${m.toUpperCase()}</b>: Sim weight ${Math.round(a.w*100)}% → ${Math.round(b.w*100)}% — over ${R.length} graded calls the ${bs<bm?'Sim':'market'} was sharper (Brier Sim ${bs.toFixed(3)} vs market ${bm.toFixed(3)}), so it ${dw>0?'leans more on the Sim':'leans more on the market'}.`);});
  if(now.brier!=null&&then.brier!=null){const d=now.brier-then.brier;out.push(`Overall Brier ${then.brier.toFixed(3)} → ${now.brier.toFixed(3)} (${d<0?'better':d>0?'worse':'flat'}); gap ${(then.ece*100).toFixed(1)} → ${(now.ece*100).toFixed(1)} pts.`);}
  return out.length?`<div class="sub" style="font-size:10px;margin-top:4px"><b>What changed this week & why:</b><br>${out.join('<br>')}</div>`:'';}
function calDrift(R){const byD={};R.forEach(x=>{(byD[x.date]=byD[x.date]||[]).push(x);});const days=Object.keys(byD).sort().slice(-14);if(!days.length)return'';
  const rows=days.map((d,i)=>{const D=byD[d];const win=days.slice(Math.max(0,i-6),i+1).flatMap(k=>byD[k]);
    const b=calBrier(D,x=>x.simP),b7=calBrier(win,x=>x.simP),e7=calECE(win);
    return`<tr><td>${d.slice(5)}</td><td>${D.length}</td><td>${Math.round(D.filter(x=>x.hit).length/D.length*100)}%</td><td>${b.toFixed(3)}</td><td>${b7.toFixed(3)}</td><td style="color:${e7<0.05?'var(--win)':e7<0.1?'var(--gold)':'var(--rust)'}">${(e7*100).toFixed(1)}</td></tr>`;}).join('');
  return`<div style="overflow-x:auto;margin-top:6px"><div class="sub" style="font-size:9.5px">Day by day — is the gap closing? (7-day rolling Brier & gap; gap under 5 pts is well calibrated)</div>
    <table class="mono" style="width:100%;font-size:10px;text-align:center"><tr style="color:var(--mute)"><td>day</td><td>n</td><td>won</td><td>Brier</td><td>7d Brier</td><td>7d gap</td></tr>${rows}</table></div>`;}
function calibrationHtml(){
  const R=calRows();try{calSnapshot();}catch(e){}
  if(R.length<20)return`<div class="tkt" style="margin-bottom:8px"><h3>Calibration</h3><div class="sub" style="color:var(--mute)">Builds as the Sim's graded calls pile up (${R.length}/20). It shows whether "60%" really wins 60% of the time — per sport, day by day.</div></div>`;
  const fsp=typeof REC_FILTER_SP!=='undefined'?REC_FILTER_SP:'all';
  const head=S=>`Brier ${calBrier(S,x=>x.simP).toFixed(3)} · gap ${(calECE(S)*100).toFixed(1)} pts · ${S.length} calls`;
  const all=`<div class="tkt" style="margin-bottom:8px"><h3>Calibration — does the ★ Sim's % come true?</h3><div class="sub mono" style="font-size:9.5px">All sports: ${head(R)} (0.25 Brier = coin flip)</div>${calTable(R)}${calDrift(R)}</div>`;
  const per=CAL_SPS.filter(sp=>fsp==='all'||fsp===sp).map(sp=>{const S=R.filter(x=>x.sp===sp);if(!S.length)return'';
    const bw=['ml','spread','total'].map(m=>{try{const b=blendWeight(sp,m);return`${m} ${Math.round(b.w*100)}% Sim (${b.n})`;}catch(e){return'';}}).filter(Boolean).join(' · ');
    return`<details class="tkt" style="margin-bottom:6px"${fsp===sp?' open':''}><summary><b>${CAL_LAB[sp]}</b> <span class="mono" style="font-size:10px;color:var(--mute)">${head(S)}</span></summary>
      ${calTable(S)}${calDrift(S)}<div class="sub mono" style="font-size:9.5px;margin-top:4px">Blend now: ${bw||'—'}</div>${calWhy(sp)}${factorHtml(sp)}</details>`;}).join('');
  return all+per;
}

/* ── 8. Risk of ruin from your own settled tickets, and correlated stakes ── */
let ROR_C=null;
function riskOfRuin(){
  const B=brAmount();if(!B)return{need:'set your bankroll'};
  const LL=roGet(LS.locked,[],30e3);const sig=B+'|'+LL.length+'|'+LL.filter(t=>t.archived).length;
  if(ROR_C&&ROR_C.sig===sig&&Date.now()-ROR_C.ts<60e3)return ROR_C.v;
  const v=riskOfRuinCore(B,LL);ROR_C={sig,ts:Date.now(),v};return v;
}
function riskOfRuinCore(B,LL){
  const L=LL.filter(t=>t.archived&&!TRACKED_ONLY_SOURCES.has(t.source));
  const R=[];const stakes=[];const W=[];L.forEach(t=>{let rec=null;try{rec=ticketIsComplete(t)?ticketRecord(t):null}catch(e){}const M=ticketMoney(t);if(!rec||!M)return;
    /* push-only ticket = stake back (0), not a full win; a parlay with a pushed leg pays only on the legs that won */
    let r;if(rec.l>0)r=-1;else if(!rec.w)r=0;else{let pay=M.payout;
      if(rec.p>0){try{const dec=(t.legs||[]).reduce((a,l)=>{const g=gradeLeg(l,t.date);const d=g&&g.hit===true?americanToDecimal(l.price):1;return a*(d>1?d:1);},1);if(dec>1)pay=M.stake*dec;}catch(e){}}
      r=(pay-M.stake)/M.stake;}
    R.push(r);stakes.push(M.stake);W.push(r>0?'w':r<0?'l':'p');});
  const wl={w:W.filter(x=>x==='w').length,l:W.filter(x=>x==='l').length,p:W.filter(x=>x==='p').length};
  if(R.length<10)return{need:'needs 10 settled tickets with a stake ('+R.length+' so far)'};
  stakes.sort((a,b)=>a-b);const f=Math.min(1,stakes[Math.floor(stakes.length/2)]/B);const r=sjRng(99);let ruin=0,half=0;
  for(let i=0;i<2000;i++){let b=1,h=false;for(let k=0;k<300;k++){b*=1+f*R[Math.floor(r()*R.length)];if(b<0.5)h=true;if(b<0.1){ruin++;break;}}if(h)half++;}
  const mu=R.reduce((a,x)=>a+x,0)/R.length;
  return{f,ruin:ruin/2000,half:half/2000,roi:mu,n:R.length,wl};
}
function riskHtml(){
  const X=riskOfRuin();if(X.need)return`<div class="tkt"><h3>Risk of ruin</h3><div class="sub" style="color:var(--mute)">${X.need}.</div></div>`;
  const col=X.ruin>0.25?'var(--rust)':X.ruin>0.08?'var(--gold)':'var(--win)';
  return`<div class="tkt"><h3>Risk of ruin</h3><div class="sub">At your typical stake (${(X.f*100).toFixed(1)}% of bankroll) and your real results so far (${X.roi>=0?'+':''}${(X.roi*100).toFixed(0)}% per ticket over ${X.n} — ${X.wl.w}-${X.wl.l}${X.wl.p?'-'+X.wl.p:''}):</div>
    <div class="sub">Chance of losing 90% of the bankroll within 300 tickets: <b style="color:${col}">${(X.ruin*100).toFixed(1)}%</b> · of halving it at some point: <b>${(X.half*100).toFixed(0)}%</b></div>
    <div class="sub mono" style="font-size:9.5px;color:var(--mute)">Replays your own ticket history 2,000 times. Under 5% is comfortable; above 25% means the stakes are too big for the edge.</div></div>`;
}
/* Same-game picks share risk: shrink each by √(picks in that game), and cap a day at 10% of bankroll. */
function correlatedStakes(rows){
  const B=brAmount();const byG={};rows.forEach(x=>{(byG[x.sp+x.game]=byG[x.sp+x.game]||[]).push(x);});
  rows.forEach(x=>{const K=kellyStake(x.blend!=null?x.blend:(x.brainP!=null?x.brainP:x.mp),x.price);x._f=K&&K.f>0?K.f/Math.sqrt(byG[x.sp+x.game].length):0;});
  const tot=rows.reduce((a,x)=>a+x._f,0);const sc=tot>0.10?0.10/tot:1;
  rows.forEach(x=>{x.stakeF=x._f*sc;x.stakeAmt=B?Math.round(B*x.stakeF*100)/100:null;x.capped=sc<1;});return rows;
}
/* pregame snapshots for MLB cards */
try{if(typeof card==='function'&&!card.__preg){const _c=card;card=function(g){return pregameWrap('mlb',g,_c.apply(this,arguments));};card.__preg=1;}}catch(e){}
/* Today tab also carries the prop scouting (Best is strictly the locked deep card) */
try{if(typeof renderToday==='function'&&!renderToday.__hp){const _rt=renderToday;renderToday=function(){const r=_rt.apply(this,arguments);
  try{const el=document.getElementById('todayBody');if(el&&!el.querySelector('.hp-sec')){const h=highPctLinesHtml()+likelyHtml();if(h)el.insertAdjacentHTML('beforeend','<div class="hp-sec">'+h+'</div>');}}catch(e){}return r;};renderToday.__hp=1;}}catch(e){}
